(window.RAAY_TB=window.RAAY_TB||{})[4]={"tel":[{"id":"te1","no":1,"t":"గాంధీ మహాత్ముడు","m":[7],"ty":"గేయం","th":"మహనీయుల చరిత్ర","by":"బసవరాజు అప్పారావు","sum":"గాంధీ మహాత్ముడు స్వాతంత్ర్య సాధన కోసం బయలుదేరగా ప్రపంచం ఆనందంతో నవ్వింది. ఆయన చకచక నడవగా భూమి కంపించింది. ఆయన కన్ను తెరవగా అధర్మం గడగడ వణికింది. ఆయన నవ్వగా స్వరాజ్యం కళ్ళెదుట కనిపించింది. ఆయన మాట్లాడగా ఓంకారం గణగణ మోగింది. ఆయన స్వస్తి పాడగా స్వరాజ్యం అనే మోక్షం మన చేతికి దొరికింది.","pts":["కవి: బసవరాజు అప్పారావు (13.12.1894 – 10.6.1933) – భావకవి, గీతకర్త. ఆయన గీతాలు “బసవరాజు అప్పారావు గేయాలు” పేరుతో వెలువడ్డాయి.","గేయంలో ధ్వన్యనుకరణ పదాలు: కలకల, చకచక, గడగడ, గణగణ.","చదవడం: సర్దార్ వల్లభాయ్ పటేల్ – స్వతంత్ర భారత మొదటి హోంమంత్రి; 565 సంస్థానాలను దేశంలో కలిపారు; 1948లో సైనిక చర్యతో హైదరాబాద్ విలీనం; బిరుదు “ఉక్కుమనిషి”.","దండి సత్యాగ్రహం (ఉప్పు సత్యాగ్రహం): 1930 మార్చి 12 – ఏప్రిల్ 6; గుజరాత్‌లోని దండి వద్ద ఉప్పు తయారు చేశారు.","పాడుదాం: “తేనెల తేటల మాటలతో” – ఇంద్రగంటి శ్రీకాంతశర్మ.","చదువుదాం: “దేశనాయకుని నిజాయితీ” – లాల్ బహదూర్ శాస్త్రి (2వ ప్రధాని); రైలు ప్రమాదానికి బాధ్యత వహించి రాజీనామా; నినాదం “జై జవాన్ – జై కిసాన్”."],"w":[["స్వరాజ్యం","సొంత పాలన"],["మోక్షం","విడుదల, విముక్తి"],["అధర్మం","ధర్మం కానిది"],["కన్నువిప్పగా","కన్ను తెరవగా"],["కన్నుల కట్టింది","కళ్ళెదుట కనిపించింది"],["ప్రణవం","ఓంకారం"],["జగత్తు","ప్రపంచం"],["కంపించుట","వణుకుట"],["కరములు","చేతులు"],["స్వస్తి","శుభం"]],"gr":{"t":"విరామ చిహ్నాలు – పూర్ణవిరామం ( . ), స్వల్పవిరామం ( , )","p":["వాక్యం చివర పెట్టే చుక్కను పూర్ణవిరామం ( . ) అంటారు. ఉదా: గీత పాఠశాలకు వెళ్ళింది.","వాక్యం మధ్యలో కొద్దిగా ఆగి చదివే చోట స్వల్పవిరామం ( , ) పెడతాం. ఉదా: అమ్మ వంకాయలు, బీరకాయలు, బెండకాయలు కొనింది.","ధ్వన్యనుకరణ పదాలు: శబ్దాన్ని అనుకరించే పదాలు – కలకల, గడగడ, గణగణ, చకచక, గలగల."]},"qa":[["స్వరాజ్యం అంటే ఏమిటి?","మన దేశాన్ని మనమే పాలించుకోవడం (సొంత పాలన)."],["గాంధీజీ బయలుదేరినప్పుడు జగత్తు ఎలా నవ్వింది?","కలకల నవ్వింది."],["గాంధీజీ చకచక నడవగా ఏమైంది?","భూదేవి (భూమి) కంపించిపోయింది."],["ఉప్పు సత్యాగ్రహం గురించి రాయండి.","బ్రిటిష్ ప్రభుత్వం ఉప్పుపై పన్ను వేసింది. దానికి నిరసనగా గాంధీజీ 1930 మార్చి 12 నుండి ఏప్రిల్ 6 వరకు దండి వరకు పాదయాత్ర చేసి ఉప్పు తయారు చేశారు."],["సర్దార్ పటేల్‌కు ఉన్న బిరుదు ఏమిటి?","ఉక్కు మనిషి."]],"act":"మన జాతీయ జెండా బొమ్మ గీసి రంగులు వేసి, జెండా గురించి నాలుగైదు వాక్యాలు రాయండి. దేశ గొప్పతనాన్ని తెలిపే పాటలు/గేయాలు సేకరించి ప్రదర్శించండి.","kn":"జాతీయ జెండాను రూపొందించినది పింగళి వెంకయ్య (ఆంధ్రప్రదేశ్). గాంధీజీని “జాతిపిత”, “బాపూజీ” అని పిలుస్తాం.","qz":[["“గాంధీ మహాత్ముడు” గేయ కవి ఎవరు?","బసవరాజు అప్పారావు","గురజాడ అప్పారావు","శ్రీశ్రీ","దాశరథి"],["గాంధీజీ బయలుదేరగా జగత్తు ఎలా నవ్వింది?","కలకల","గలగల","కిలకిల","పకపక"],["గాంధీజీ చకచక నడవగా ఏమి కంపించిపోయింది?","భూదేవి","ఆకాశం","సముద్రం","కొండ"],["గాంధీజీ కన్ను విప్పగా గడగడ వణికింది ఏది?","అధర్మము","ప్రణవము","స్వరాజ్యం","మోక్షము"],["“ప్రణవం” అంటే అర్థం?","ఓంకారం","ప్రపంచం","శుభం","చేతులు"],["“కరములు” అంటే?","చేతులు","కాళ్ళు","కళ్ళు","చెవులు"],["“స్వస్తి” అంటే?","శుభం","విముక్తి","సొంత పాలన","ఓంకారం"],["స్వతంత్ర భారత మొదటి హోంమంత్రి ఎవరు?","సర్దార్ వల్లభాయ్ పటేల్","జవహర్‌లాల్ నెహ్రూ","అంబేద్కర్","లాల్ బహదూర్ శాస్త్రి"],["సర్దార్ పటేల్ బిరుదు ఏమిటి?","ఉక్కు మనిషి","జాతిపిత","ఆంధ్రకేసరి","చాచాజీ"],["దండి సత్యాగ్రహం ఏ సంవత్సరంలో జరిగింది?","1930","1947","1920","1942"],["“జై జవాన్ – జై కిసాన్” నినాదం ఎవరిది?","లాల్ బహదూర్ శాస్త్రి","గాంధీజీ","నెహ్రూ","పటేల్"],["వాక్యం చివర పెట్టే గుర్తు ( . ) పేరు?","పూర్ణవిరామం","స్వల్పవిరామం","ప్రశ్నార్థకం","ఆశ్చర్యార్థకం"],["కిందివాటిలో ధ్వన్యనుకరణ పదం ఏది?","గణగణ","స్వరాజ్యం","భూదేవి","మోక్షం"]],"wb":{"pg":"2–10","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":8,"ws":["సాధనపత్రం 1–2: చదవడం – వ్యక్తపరచడం (పేరా, గేయ భావం, ప్రశ్నలు తయారు)","సాధనపత్రం 3–5: పదజాలం (సరళ/గుణింత/ద్విత్వ/సంయుక్తాక్షరాలు, అనుకరణ పదాలు, గళ్ళ పదాలు, అంత్యాక్షరి)","సాధనపత్రం 6: స్వీయరచన","సాధనపత్రం 7: భాషాంశాలు – విరామ చిహ్నాలు (. ,)","సాధనపత్రం 8: సృజనాత్మకత (వందనం గేయం, చుక్కల బొమ్మ)","నేనేమి నేర్చుకున్నాను?"],"mis":"స్వల్పవిరామం ( , ) పదాల జాబితా మధ్యలో, పూర్ణవిరామం ( . ) వాక్యం చివర మాత్రమే. ✗ “రవి. రాజు స్నేహితులు, వారు …” ✓ “రవి, రాజు స్నేహితులు. వారు గాజుల వ్యాపారం చేస్తారు.”","qz":[["దీపక్ నిజాయితీ కలవాడని ఎలా చెప్పవచ్చు?","పర్సును ఉపాధ్యాయునికి ఇవ్వడం","పర్సులో డబ్బులు వాడుకోవడం","పర్సును పారవేయడం","పర్సును మిత్రునికి ఇవ్వడం"],["“కన్నుల గట్టింది స్వరాజ్యం” – భావం?","స్వరాజ్యం కళ్ళెదుట కనిపించింది","స్వరాజ్యం పోయింది","కళ్ళకు గంతలు కట్టారు","స్వరాజ్యం కష్టం"],["“వనజ ___ వణికింది.” సరైన అనుకరణ పదం?","గజగజ","పకపక","చకచక","గబగబ"],["“స్వస్తి” అంటే?","శుభం","ఓంకారం","ధర్మం","సంతోషం"],["“మోక్షం” అర్థం?","విముక్తి","కోపం","సొంత పాలన","ప్రపంచం"],["సరైన విరామ చిహ్నాలు ఉన్న వాక్యం?","రవి, రాజు స్నేహితులు. వారు గాజుల వ్యాపారం చేస్తారు.","రవి రాజు స్నేహితులు, వారు. గాజుల వ్యాపారం చేస్తారు","రవి. రాజు, స్నేహితులు వారు గాజుల వ్యాపారం చేస్తారు","రవి రాజు స్నేహితులు వారు గాజుల వ్యాపారం చేస్తారు"],["కేవలం పూర్ణ విరామం ( . ) మాత్రమే ఉన్న వాక్యం?","రైతు పొలానికి వెళ్ళాడు.","అమల, విమల పాఠశాలకు వచ్చారు.","పిల్లలు చదువుకొని, ఆటలు ఆడారు.","అమ్మ అరిసెలు, కజ్జికాయలు తెచ్చింది."],["జెండాలో అశోకచక్రంలో ఎన్ని చువ్వలు?","24","12","20","32"],["జెండా పొడవు : వెడల్పు నిష్పత్తి?","3:2","2:1","1:1","4:3"],["ప్రణవము అంటే?","ఓంకారం","ప్రపంచం","మోక్షం","అధర్మం"],["అంత్యాక్షరిలో “కరము” తర్వాత వచ్చే పదం?","ముక్కెర","కలం","రథం","గులాబి"],["“తక్కువ” కు వ్యతిరేక పదం?","ఎక్కువ","తగ్గు","చిన్న","కొంచెం"]]},"tg":[["చిత్రం చూడండి – ఆలోచించి మాట్లాడండి (పుట 1)",["1. చిత్రంలో ఝాన్సీ లక్ష్మీబాయి గుర్రం మీద కత్తి పట్టి బ్రిటిష్ సైనికులతో యుద్ధం చేస్తోంది.","2. కోట దగ్గర యుద్ధం జరుగుతోంది; ఫిరంగులు పేలుతున్నాయి – స్వాతంత్ర్య పోరాట సన్నివేశం.","3. గాంధీజీ, నెహ్రూ, సుభాష్ చంద్రబోస్, భగత్‌సింగ్, అల్లూరి సీతారామరాజు, ఝాన్సీ లక్ష్మీబాయి, టంగుటూరి ప్రకాశం."]],["ఇవి చేయండి – వినడం, ఆలోచించి మాట్లాడటం (పుట 4)",["1. గాంధీజీ బయలుదేరినప్పుడు జగత్తు కలకల నవ్వింది.","2. ప్రణవం అంటే ఓంకారం.","3. గుడిలో, బడిలో, చర్చిలో గంటలు మోగుతాయి.","4. గాంధీజీ, నెహ్రూ, పటేల్, సుభాష్ చంద్రబోస్, అంబేద్కర్, లాల్ బహదూర్ శాస్త్రి."]],["చదవడం – వ్యక్తపరచడం (పుట 5)",["1. సి) వల్లభాయ్ పటేల్","2. సి) జమ్మూకాశ్మీర్","3. ఉక్కు మనిషి","4. విలీనం = కలిసిపోవడం","5. 1948లో సైనిక చర్య ద్వారా హైదరాబాద్ సంస్థానాన్ని భారతదేశంలో విలీనం చేశారు."]],["పదజాలం (పుట 6)",["అ) గుర్తించిన పదాలు: గాంధీజీ, పోయింది, కంపించి, గడగడ, వణికింది, నడువగ, భూదేవి, చకచక","గా – గాలి, గాజు, గాడిద | పో – పోరు, పోటీ | కం – కందిరీగ, కంచం | చ – చలిగాలి, చక్రం","వ – వల, వరి | న – నలక, నది | భూ – భూదేవి, భూమి | గ – గజగజ, గడియారం"]],["స్వీయరచన (పుట 6)",["అ) స్వరాజ్యం అంటే మనల్ని మనమే పాలించుకోవడం.","ఆ) గాంధీజీ చకచక నడిచినప్పుడు భూమి కంపించిపోయిందని కవి చెప్పాడు.","ఇ) వందేమాతరం, క్విట్ ఇండియా, జై హింద్, సత్యమేవ జయతే.","ఈ) 1930లో ఉప్పుపై పన్నుకు నిరసనగా గాంధీజీ దండి వరకు పాదయాత్ర చేసి ఉప్పు తయారు చేశారు.","ఉ) గేయ సారాంశం: గాంధీజీ బయలుదేరగా లోకం సంతోషించింది, అధర్మం వణికింది, స్వరాజ్యం కళ్ళముందుకు వచ్చింది.","ఊ) గాంధీజీ సత్యం, అహింసలతో పోరాడి మనకు స్వాతంత్ర్యం తెచ్చారు."]],["సృజనాత్మకత / ప్రశంస / భాషాంశాలు (పుట 7)",["సృజనాత్మకత: జెండా బొమ్మ గీసి – “మన జెండాలో కాషాయం, తెలుపు, ఆకుపచ్చ రంగులు ఉంటాయి. మధ్యలో 24 చువ్వల అశోకచక్రం ఉంటుంది. దీనిని పింగళి వెంకయ్య రూపొందించారు.”","ప్రశంస: “మన దేశ స్వాతంత్ర్యం కోసం ప్రాణాలకు తెగించి పోరాడిన మీకు వందనాలు!”","భాషాంశాలు: 1. గీత పాఠశాలకు వెళ్ళింది.  2. అమ్మ బజారులో వంకాయలు, బీరకాయలు, బెండకాయలు కొనింది."]],["నేనేమి నేర్చుకున్నాను? (పుట 11)",["1. అన్నీ ద్విత్వాక్షర పదాలు సరైనవే (వెన్నెల, పట్టీలు, చిన్న పిల్ల, కన్నులు) – పుస్తకంలో తప్పు ముద్రణ ఉంటే సరిచూడండి.","2. గాంధీజీ అధర్మాన్ని (హింసను, బానిసత్వాన్ని) వదిలిపెట్టమని చెప్పారు.","3. i) ఆ) చీమ  ii) మిడత ముందు జాగ్రత్తగా ఆహారం దాచుకోలేదు. నీతి: భవిష్యత్తు కోసం ముందే కష్టపడాలి.","4. కలకల, గడగడ (గణగణ, చకచక).","5–8. పిల్లల సొంత జవాబులు (ఉదా: గాంధీజీ సత్యం, అహింసలతో దేశానికి స్వాతంత్ర్యం తెచ్చారు)."]]]},{"id":"te2","no":2,"t":"గోపాల్ తెలివి","m":[7],"ty":"కథ","th":"సమయస్ఫూర్తి","by":"జానపద కథ","sum":"ఢిల్లీ సుల్తాన్ సామంత రాజులకు రెండు చిక్కు ప్రశ్నలు వేశాడు – “ఈ భూమి పొడవు, వెడల్పు ఎంత? ఆకాశంలో ఎన్ని నక్షత్రాలు ఉన్నాయి?” ఎవరూ జవాబు చెప్పలేకపోయారు. మాల్వా రాజు జయచంద్రుని ఆస్థాన విదూషకుడు గోపాల్ సుల్తాన్ దగ్గరికి వెళ్ళి సంవత్సరం గడువు, డబ్బు తీసుకున్నాడు. రాట్నాల వాళ్లతో దారం వడికించి ఎనిమిది బండ్ల దారం, గొర్రెలను తెచ్చి “ఈ దారంతో భూమి పొడవు వెడల్పులు కొలిచాను; ఒక్కో నక్షత్రానికి ఒక్కో గొర్రె వెంట్రుక – లెక్కపెట్టుకోండి” అన్నాడు. సుల్తాన్ పకపకా నవ్వి గోపాల్‌ను సన్మానించాడు.","pts":["పాత్రలు: ఢిల్లీ సుల్తాన్, సామంత రాజులు, మాల్వా రాజు జయచంద్రుడు, విదూషకుడు గోపాల్.","సుల్తాన్ ప్రశ్నలు: 1. భూమి పొడవు, వెడల్పు ఎంత? 2. ఆకాశంలో ఎన్ని నక్షత్రాలు?","గోపాల్ జవాబు: ఎనిమిది బండ్ల దారం (కొలత) + గొర్రెల వెంట్రుకలు (నక్షత్రాల సంఖ్య).","చదవడం: మూడు చేపలు – దీర్ఘదర్శి (ముందే ఊహించేది), ప్రాప్తకాలజ్ఞుడు, దీర్ఘసూత్రుడు.","పాత కొలతలు: బెత్తెడు (4 వేళ్ళ వెడల్పు), జాన (బొటనవేలు – చిటికెన వేలు), మూర (మోచేయి – మధ్యవేలి చివర), బార (రెండు చేతులు చాచితే).","పాడుదాం: “బ్రహ్మమొక్కటే” – తాళ్ళపాక అన్నమయ్య (1408–1503), పదకవితా పితామహుడు, 32 వేల సంకీర్తనలు.","చదువుదాం: “చిక్కుప్రశ్న – వివేకవంతమైన జవాబు” – వెన్నెల జవాబు “వెయ్యి నూట పదహారు”."],"w":[["దర్బారు","రాజసభ"],["విదూషకుడు","హాస్యగాడు"],["సామంతులు","రాజు కింద ఉండే చిన్న రాజులు"],["కఠినమైన","కష్టమైన"],["ప్రత్యక్షం","కళ్ళముందు కనిపించడం"],["గంభీరంగా","హుందాగా"],["మథనపడు","లోలోపల బాధపడు"],["ప్రశంసించు","పొగడు"],["దిగులు","విచారం, బాధ"],["ఆస్థానం","రాజసభ"],["నిశ్చింత","ఆందోళన లేకపోవడం"],["తమాషా","వినోదం, హాస్యం"]],"gr":{"t":"ఆశ్చర్యార్థక చిహ్నం ( ! ) • గుణింత, ద్విత్వ, సంయుక్తాక్షరాలు","p":["ఆశ్చర్యం, ఆనందం, కోపం, బాధ, ఉత్సాహం తెలిపే చోట ( ! ) పెడతాం. ఉదా: ఆహా! ఎంత చల్లని గాలి! శభాష్! నువ్వు బాగా చదువుతున్నావు!","ద్విత్వాక్షరం: ఒకే హల్లు వత్తు – చెట్టు, అక్క. సంయుక్తాక్షరం: వేరే హల్లు వత్తు – నక్షత్రం, ప్రశ్న.","పొడుపు కథ ఉదా: నాకు నాలుగు కాళ్ళు ఉంటాయి కానీ నడవలేను … – కుర్చీ."]},"qa":[["సుల్తాన్ అడిగిన ప్రశ్నలు ఏమిటి?","భూమి పొడవు, వెడల్పు ఎంత? ఆకాశంలో ఎన్ని నక్షత్రాలు ఉన్నాయి?"],["గోపాల్ ఎవరు?","మాల్వా రాజు జయచంద్రుని ఆస్థాన విదూషకుడు."],["గోపాల్ భూమి పొడవు వెడల్పులు ఎలా కొలిచానన్నాడు?","ఎనిమిది బండ్ల దారంతో పొడవు, మరో ఎనిమిది బండ్ల దారంతో వెడల్పు కొలిచానన్నాడు."],["నక్షత్రాలను ఎలా లెక్కించానన్నాడు?","ఒక్కో నక్షత్రానికి ఒక్కో గొర్రె వెంట్రుక – ఆ వెంట్రుకలు లెక్కపెట్టుకోమన్నాడు."]],"act":"రెండు పొడుపు కథలు రాయండి. మీ పాఠశాల గ్రంథాలయంలో కథలు చదివి నచ్చిన అంశాలు రాయండి. జాన, మూరలతో మీ బల్ల పొడవు కొలవండి.","kn":"“ఇంతేనా! దీనికి దిగులుపడతారెందుకు?” – గోపాల్ సమయస్ఫూర్తికి నిదర్శనం.","qz":[["సుల్తాన్ ఏ నగరానికి రాజు?","ఢిల్లీ","మాల్వా","ఆగ్రా","హైదరాబాద్"],["మాల్వా రాజు పేరు?","జయచంద్రుడు","అక్బర్","గోపాల్","శ్రీకృష్ణదేవరాయలు"],["గోపాల్ ఎవరు?","ఆస్థాన విదూషకుడు","సేనాపతి","మంత్రి","సామంతరాజు"],["గోపాల్‌కు సుల్తాన్ ఇచ్చిన గడువు?","ఒక సంవత్సరం","ఒక నెల","ఒక వారం","ఒక రోజు"],["భూమిని కొలవడానికి గోపాల్ తెచ్చినది?","దారం బండ్లు","కర్రలు","తాళ్ళు","రాళ్ళు"],["నక్షత్రాల లెక్కకు గోపాల్ చూపినది?","గొర్రె వెంట్రుకలు","ఇసుక రేణువులు","బియ్యం గింజలు","ఆకులు"],["“విదూషకుడు” అంటే?","హాస్యగాడు","రాజు","సైనికుడు","కవి"],["“నిశ్చింత” అంటే?","ఆందోళన లేకపోవడం","దిగులు","కోపం","సంతోషం"],["మూడు చేపల్లో ముందే ఆపదను ఊహించినది?","దీర్ఘదర్శి","దీర్ఘసూత్రుడు","ప్రాప్తకాలజ్ఞుడు","దీర్ఘకాలుడు"],["రెండు చేతులు చాచితే వచ్చే కొలత?","బార","జాన","మూర","బెత్తెడు"],["“బ్రహ్మమొక్కటే” కీర్తన రాసినవారు?","అన్నమయ్య","త్యాగయ్య","వేమన","పోతన"],["ఆశ్చర్యార్థక చిహ్నం ఏది?","!","?",",","."],["“సమాధానం” అర్థం?","జవాబు","ప్రశ్న","కథ","దిగులు"]],"wb":{"pg":"11–19","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":17,"ws":["సాధనపత్రం 1–2: చదవడం – వ్యక్తపరచడం (ఎవరు ఎవరితో అన్నారు, కుందేళ్ళ కథ, సంభాషణ)","సాధనపత్రం 3–5: పదజాలం (అక్షరాలు, అర్థాలు, వర్గీకరణ, వచనాలు, జంట పదాలు, వ్యతిరేకాలు, పండ్లు–కూరగాయల గళ్ళు)","సాధనపత్రం 6: స్వీయరచన","సాధనపత్రం 7: భాషాంశాలు – ఆశ్చర్యార్థకం ( ! )","సాధనపత్రం 8: సృజనాత్మకత (రెక్కలు వస్తే, రెక్కల గుర్రం)","నేనేమి నేర్చుకున్నాను?"],"mis":"( ! ) భావం బయటపడే పదం తర్వాతే పెట్టాలి: ✓ “ఇంతేనా! దీనికి దిగులు పడతారెందుకు?” ✗ “ఇంతేనా దీనికి! దిగులు…”. జంట పదాలు కలిపి రాయాలి – తల్లిదండ్రులు, తెలివితేటలు.","qz":[["“రాజా! ఎటువంటి చిక్కు ప్రశ్నకైనా సమాధానం ఉండకతప్పదు” అన్నది?","గోపాల్","సుల్తాన్","జయచంద్రుడు","సామంతులు"],["వలలో చిక్కుకున్న కుందేలు?","మూడవ కుందేలు","మొదటి కుందేలు","రెండవ కుందేలు","అన్నీ"],["“శీఘ్రంగా” అర్థం?","వెంటనే","ఆలస్యం","తరువాత","నెమ్మదిగా"],["కింది వాటిలో పక్షి?","కొంగ","జింక","ఆటో","సింహం"],["“నక్షత్రం” బహువచనం?","నక్షత్రాలు","నక్షత్రలు","నక్షత్రము","నక్షత్రులు"],["“తెలివి” జంట పదం?","తెలివితేటలు","తెలివిసంధ్యలు","తెలివిదండ్రులు","తెలివిభాగ్యాలు"],["“పొడవు” వ్యతిరేకం?","పొట్టి","సన్నం","లావు","ఎత్తు"],["గళ్ళలో దాగిన పండు?","ద్రాక్ష","బెండకాయ","ఉల్లి","టమాట"],["( ! ) ఏ పదం పక్కన ఉంచాలి – “ఇంతేనా దీనికి దిగులు పడతారెందుకు”?","ఇంతేనా!","దీనికి!","దిగులు!","పడతారెందుకు!"],["“జంట పదాలు” కానిది?","పచ్చని చెట్లు","కష్టసుఖాలు","భోగభాగ్యాలు","చదువుసంధ్యలు"],["“ప్రత్యక్షమయ్యాడు” అంటే?","కళ్ళముందు కనిపించాడు","వెళ్ళిపోయాడు","దాక్కున్నాడు","నిద్రపోయాడు"],["గోపాల్ రాజు ఆస్థానంలో ఏ పని చేసేవాడు?","హాస్యంతో నవ్వించడం","యుద్ధం చేయడం","పన్నులు వసూలు","వంట చేయడం"]]},"tg":[["చిత్రం చూడండి – ఆలోచించి మాట్లాడండి (పుట 12)",["1. అడవిలో మేకలు, పెద్ద గొయ్యి కనిపిస్తున్నాయి.","2. కథ: మేకలు మేత మేస్తూ ఒకదాని వెంట ఒకటి గోతిలో పడ్డాయి. బయటకు రాలేక భయపడ్డాయి. ఒక తెలివైన మేక కర్రలు, కొమ్మలు గోతిలోకి వేసి వాటి మీదుగా పైకి ఎక్కి బయటపడింది. ఆపదలో తెలివిగా ఆలోచించాలి."]],["ఇవి చేయండి – వినడం, ఆలోచించి మాట్లాడటం (పుట 16)",["1. సామంతులకు రెండు ప్రశ్నలు వేసి జవాబులు అడగాలనే ఆలోచన.","2. భూమి పొడవు వెడల్పులు, నక్షత్రాల సంఖ్య. చిక్కుసమస్య = సులభంగా పరిష్కరించలేని సమస్య. ఉదా: తోక లేని పిట్ట తొంభై ఆమడలు పోతుంది – ఉత్తరం.","3. పిల్లలు కథను సొంత మాటల్లో చెప్పాలి."]],["చదవడం – వ్యక్తపరచడం (పుట 16–17)",["1. ఆ) దీర్ఘకాలుడు","2. దీర్ఘదర్శి","3. వేసవి కాలం (ఎండాకాలం) గురించి ఆలోచించి – మడుగు ఎండిపోతుందని.","4. రానున్న వేసవికాలంలో మడుగు ఎండిపోతుందని దీర్ఘదర్శి ఊహించింది."]],["పదజాలం (పుట 17)",["అ) గుణింతాక్షర: సుల్తాను, రాజు, భూమి | ద్విత్వాక్షర: పట్టణం, చిక్కు, గొర్రె | సంయుక్తాక్షర: నక్షత్రాలు, ప్రశ్నలు, ప్రత్యక్షం","ఇ) రంగురంగుల బొమ్మలు – వేసేస్తాం, మైదానంలో ఆటలు – ఆడేస్తాం, చిట్టిచిట్టి కథలు – చెప్పేస్తాం, కాగితం పడవలు – వదిలేస్తాం, ఊహల ఊయలు – ఊగేస్తాం"]],["స్వీయరచన / సృజనాత్మకత (పుట 18)",["1. భూమి పొడవు వెడల్పులు ఎంత? ఆకాశంలో నక్షత్రాలు ఎన్ని?","2. మాల్వా రాజు జయచంద్రుని ఆస్థాన విదూషకుడు.","3. ఎనిమిది బండ్ల దారంతో కొలిచానన్నాడు.","4. ఒక్కో నక్షత్రానికి ఒక్కో గొర్రె వెంట్రుక అన్నాడు.","పొడుపు కథలు: “తెల్లని చేనులో నల్లని విత్తనాలు, చేత్తో విత్తుతారు, నోటితో ఏరుతారు” – పుస్తకం/అక్షరాలు. “కాళ్ళు లేవు కానీ నడుస్తుంది, చేతులు లేవు కానీ చూపిస్తుంది” – గడియారం."]],["ప్రశంస / భాషాంశాలు (పుట 18–19)",["ప్రశంస: (ఉదా) చిత్రలేఖన పోటీలో బహుమతి వచ్చినప్పుడు మా ఉపాధ్యాయులు “శభాష్!” అని అందరి ముందు అభినందించారు.","( ! ) చుట్టవలసిన పదాలు: అబ్బో!, అవును!, బాబోయ్!, చూడండి!","1. ఆహా! ఎంత చల్లని గాలి!  2. శభాష్! నువ్వు బాగా చదువుతున్నావు!"]],["నేనేమి నేర్చుకున్నాను? (పుట 22)",["1. ఈ) రాజు (మాల్వా రాజు జయచంద్రుడు)","2. విషమించు = తీవ్రమగు / ప్రమాదకరంగా మారు","3. “తెలివైనవాడు” – విశేషణం","4. i) ఇ) నిజాయితీగా  ii) దొరికిన డబ్బు పోలీసులకు అప్పగించినందుకు మెచ్చుకున్నారు. నేనూ అలాగే చేస్తాను.","5. సన్మానం – పోటీలో గెలిచిన వారికి సన్మానం చేశారు. బహుమతి – నాకు చదువులో బహుమతి వచ్చింది.","6–8. పిల్లల సొంత జవాబులు."]]]},{"id":"te3","no":3,"t":"దేశమును ప్రేమించుమన్నా","m":[8],"ty":"గేయం","th":"దేశభక్తి","by":"గురజాడ వేంకట అప్పారావు","sum":"దేశాన్ని ప్రేమించాలి, మంచిని పెంచాలి. వట్టి మాటలు కట్టిపెట్టి గట్టి మేలు తలపెట్టాలి. పాడిపంటలు పొంగిపొర్లే దారిలో కష్టపడాలి. తిండి కలిగితే కండ కలుగుతుంది, కండ ఉన్నవాడే మనిషి. దేశాభిమానం ఉందని గొప్పలు చెప్పుకోకుండా మేలు చేసి చూపాలి. సొంత లాభం కొంత మానుకొని పొరుగువారికి సాయపడాలి. దేశమంటే మట్టి కాదు, దేశమంటే మనుషులు. దేశస్థులంతా చెట్టపట్టాలు పట్టుకొని అన్నదమ్ముల్లా కలిసి మెలగాలి.","pts":["కవి: గురజాడ వేంకట అప్పారావు (21.9.1862 – 30.11.1915) – యుగకర్త, ఆధునిక తెలుగు కవి. “కన్యాశుల్కం” నాటకం; వాడుక భాషలో రచనలు.","ముఖ్య పాదం: “దేశమంటే మట్టి కాదోయ్ – దేశమంటే మనుషులోయ్”.","“తిండి కలిగితె కండ కలదోయ్ – కండ కలవాడేను మనిషోయ్”.","జాతీయ జెండా: కాషాయం (త్యాగం), తెలుపు (శాంతి), ఆకుపచ్చ (పాడిపంటలు); అశోకచక్రంలో 24 చువ్వలు; పొడవు:వెడల్పు = 3:2; రూపకర్త పింగళి వెంకయ్య.","పాడుదాం: “తెలుగు తల్లి” – పిల్లలమర్రి వేంకట హనుమంతరావు.","చదువుదాం: “ఆంధ్రకేసరి” టంగుటూరి ప్రకాశం పంతులు – బ్రిటిష్ తుపాకులకు ఛాతీ చూపి “కాల్చండి!” అన్నారు; ఉమ్మడి ఆంధ్ర రాష్ట్ర తొలి ముఖ్యమంత్రి."],"w":[["ఒట్టి","ఏమీ లేని"],["కద్దు","కలదు, ఉన్నది"],["దేశాభిమానం","దేశం మీద ప్రేమ"],["చెట్టపట్టాలు","ఒకరి చేతిని మరొకరు పట్టుకోవడం"],["తోడుపడు","సహాయపడు"],["కట్టిపెట్టు","ఆపివేయు"],["తలపెట్టు","మొదలుపెట్టు"],["పాటుపడు","కష్టపడు"],["మేలు","ఉపకారం, మంచి"],["దేశస్థులు","దేశంలోని ప్రజలు"]],"gr":{"t":"ప్రశ్నార్థక చిహ్నం ( ? ) • ఏకవచనం – బహువచనం","p":["ప్రశ్న అడిగే వాక్యం చివర ( ? ) పెడతాం. ఎప్పుడు, ఎక్కడ, ఏ, ఏది, ఎవరు, ఎటువైపు – ప్రశ్నార్థక పదాలు.","ఉదా: మీకు ఏయే పండ్లు ఇష్టం? రైలు నిలయంలో ఏ రకాల టికెట్లు లభిస్తాయి?","బహువచనం: పంట – పంటలు, దేశం – దేశాలు, చేయి – చేతులు, కబురు – కబుర్లు."]},"qa":[["దేశాన్ని ఎలా ప్రేమించాలని కవి అన్నాడు?","వట్టి గొప్పలు చెప్పకుండా, మంచి పనులు చేసి, పొరుగువారికి సాయపడి, అందరితో అన్నదమ్ముల్లా కలిసి మెలిగి దేశాన్ని ప్రేమించాలి."],["దేశమంటే ఏమిటి?","దేశమంటే మట్టి కాదు, దేశమంటే మనుషులు."],["జాతులు, మతాలు ఎలా మెలగాలి?","అన్నదమ్ముల్లా కలిసిమెలిసి మెలగాలి."],["జెండాలోని రంగులు ఏమి సూచిస్తాయి?","కాషాయం – త్యాగం, తెలుపు – శాంతి, ఆకుపచ్చ – పాడిపంటలు."]],"act":"“వందనం వందనం – భరతమాతకు వందనం” గేయాన్ని పొడిగించండి. దేశనాయకుల చిత్రాలు సేకరించి వారి సేవల గురించి నాలుగైదు వాక్యాలు రాయండి.","kn":"జాతీయ పతాక నియమావళి 2002 ప్రకారం జెండాను నేలకు తాకించరాదు, తలకిందులుగా ఎగురవేయరాదు; సూర్యోదయానికి ఎగురవేసి సూర్యాస్తమయానికి దించాలి.","qz":[["“దేశమును ప్రేమించుమన్నా” గేయ రచయిత?","గురజాడ అప్పారావు","బసవరాజు అప్పారావు","శ్రీశ్రీ","దాశరథి"],["గురజాడ రాసిన ప్రసిద్ధ నాటకం?","కన్యాశుల్కం","మహాప్రస్థానం","అగ్నిధార","గుజ్జనగూళ్ళు"],["“దేశమంటే మట్టి కాదోయ్ – దేశమంటే ___”","మనుషులోయ్","పంటలోయ్","కొండలోయ్","నదులోయ్"],["“తిండి కలిగితె ___ కలదోయ్”","కండ","కొండ","పండ","దండ"],["“చెట్టపట్టాలు” అంటే?","ఒకరి చేతిని మరొకరు పట్టుకోవడం","చెట్లు ఎక్కడం","గొడవ పడటం","విడిపోవడం"],["“కద్దు” అర్థం?","కలదు","లేదు","కాదు","వద్దు"],["“పాటుపడు” అంటే?","కష్టపడు","పాట పాడు","పడుకో","పారిపో"],["జాతులు, మతాలు ఎలా మెలగాలి?","అన్నదమ్ముల వలె","శత్రువుల వలె","వేరువేరుగా","పోటీగా"],["అశోకచక్రంలో చువ్వలు?","24","12","16","30"],["జాతీయ జెండా రూపకర్త?","పింగళి వెంకయ్య","టంగుటూరి ప్రకాశం","గాంధీజీ","నెహ్రూ"],["“ఆంధ్రకేసరి” అని ఎవరిని పిలుస్తారు?","టంగుటూరి ప్రకాశం పంతులు","పొట్టి శ్రీరాములు","అల్లూరి సీతారామరాజు","పటేల్"],["ప్రశ్నార్థక చిహ్నం?","?","!",".",","],["“చేయి” బహువచనం?","చేతులు","చేయిలు","చేయులు","చేతిలు"]],"wb":{"pg":"20–28","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":26,"ws":["సాధనపత్రం 1–2: చదవడం (కరణం మల్లీశ్వరి, అల్లూరి సీతారామరాజు, గేయ పాదాలు పూరించడం)","సాధనపత్రం 3–4: పదజాలం (అక్షరాలు, గేయ పాదాల జతలు, ద్విత్వ పదాలు, నానార్థాలు, పక్షి – లక్షణం)","సాధనపత్రం 5: స్వీయరచన","సాధనపత్రం 6–7: భాషాంశాలు – ( . , ! ? ) మరియు ప్రశ్నార్థక వాక్యాలు","సాధనపత్రం 8: సృజనాత్మకత (సంభాషణ, చుక్కల బొమ్మ)","నేనేమి నేర్చుకున్నాను?"],"mis":"ప్రశ్నార్థక పదం (ఎవరు, ఎక్కడ, ఎప్పుడు, ఏది) ఉన్న వాక్యం చివర ( ? ) పెట్టాలి; ఆశ్చర్యానికి ( ! ). ✗ “నువ్వు ఏయే ఆటలు ఆడుతావు.” ✓ “నువ్వు ఏయే ఆటలు ఆడుతావు?”","qz":[["భారతదేశానికి వెయిట్‌లిఫ్టింగ్‌లో ఒలింపిక్ పతకం సాధించిన మహిళ?","కరణం మల్లీశ్వరి","పి.వి. సింధు","మేరీ కోమ్","సైనా నెహ్వాల్"],["అల్లూరి సీతారామరాజు ఎవరిని చైతన్యపరిచారు?","మన్యంవాసులను","బ్రిటిష్‌వారిని","నల్లమలవాసులను","విశాఖవాసులను"],["“సిద్ధం” అర్థం?","తయారు","భయం","నిద్ర","కోపం"],["“ఒట్టి మాటలు” జత పదం?","కట్టిపెట్టోయ్","చెప్పుకోకోయ్","కండకలదోయ్","తోడుపడవోయ్"],["“డేగ” కు సరిపోయేది?","చూపు","గానం","నాట్యం","నడక"],["“నెమలి” కు సరిపోయేది?","నాట్యం","గూడు","పలుకు","గోల"],["సంయుక్తాక్షర పదం ఏది?","పొంగిపొర్లే","ఒట్టిమాటలు","చెప్పుకోకోయ్","అన్నదమ్ములు"],["“కబురు” బహువచనం?","కబుర్లు","కబురులు","కబుర్లులు","కబురాలు"],["ప్రశ్నార్థక గుర్తు ఏ పదం వచ్చినప్పుడు వాడతాం?","ఎక్కడ","ఉన్నారు","తిన్నారు","ఇక్కడ"],["సరైన వాక్యం?","అబ్బో! నీ జుట్టు ఎంత పొడవుగా ఉందో!","నువ్వు ఇంటికి ఎలా వస్తావు.","అమ్మాయి, ఇలా రా,","నువ్వు బాగా చదువుతున్నావు?"],["“చెట్ల ఆకులతో తోరణాలు కడతారు” – ఏ చెట్టు?","మామిడి","తాటి","ఉసిరి","నిమ్మ"],["చెట్లు మనకు ఇచ్చే ముఖ్యమైన వాయువు?","ఆక్సిజన్","పొగ","దుమ్ము","కాలుష్యం"]]},"tg":[["చిత్రం చూడండి – ఆలోచించి మాట్లాడండి (పుట 23)",["1. పాఠశాల, జాతీయ జెండా, మొక్కలు, నీళ్ళ డబ్బా, జెండా బొమ్మ గీస్తున్న పిల్లలు ఉన్నారు.","2. స్వాతంత్ర్య దినోత్సవం (ఆగస్టు 15), గణతంత్ర దినోత్సవం (జనవరి 26) నాడు జెండా ఎగురవేస్తారు.","3. కాషాయం, తెలుపు, ఆకుపచ్చ; మధ్యలో నీలి రంగు అశోకచక్రం."]],["ఇవి చేయండి – వినడం, ఆలోచించి మాట్లాడటం (పుట 27)",["1. దేశ నియమాలు పాటిస్తాను, పరిసరాలు శుభ్రంగా ఉంచుతాను, అందరికీ సాయం చేస్తాను.","2. గేయ సారాంశం: దేశాన్ని ప్రేమించి, మంచి పనులు చేసి, అందరూ కలిసిమెలిసి ఉండాలి.","3. దేశమంటే మనుషులు; దేశ ప్రజలకు మేలు చేయడమే దేశభక్తి.","4. పొరుగువారికి సహాయపడాలి.","5. అన్నదమ్ముల్లా కలిసి మెలగాలి."]],["చదవడం – వ్యక్తపరచడం (పుట 27)",["అ) 1. వట్టి మాటలు కట్టిపెట్టి, ప్రజలకు ఉపయోగపడే మంచి పని చేసి చూపాలి.","2. జాతులు, మతాలన్నీ అన్నదమ్ముల్లా కలిసిమెలిసి ఉండాలని కవి చెప్పారు.","ఆ) 1. అ) ఆనందం కొరకు","2. పండుగలు ఆనందాన్ని పంచుకోవడానికి; ఆనందానికి మతం ఉండదు అన్నారు.","3. అందరం కలిసిమెలిసి ఉంటాం, స్నేహం పెరుగుతుంది.","4. పిల్లల సొంత జవాబు."]],["పదజాలం (పుట 28)",["అ) చెట్ల పేర్లు: మామిడి, రావి, వేప, అశోక, నిమ్మ, ఉసిరి, తాటి, సపోటా, కొబ్బరి (గళ్ళలో వెతకండి)","ఆ) ఉదా: వేప చెట్టు నీడ చల్లగా ఉంటుంది. ఉసిరిలో విటమిన్-సి ఎక్కువ."]],["స్వీయరచన (పుట 28)",["1. గొప్పలు చెప్పకుండా మేలు చేసి చూపాలి.","2. చదువులో, పనుల్లో తోటివారికి సాయం చేస్తాను.","3. అన్నదమ్ముల్లా.","4. భారతీయులందరం సోదరులం; కలిసి ఉంటే బలం.","5. జెండాను, జాతీయ గీతాన్ని గౌరవించి, దేశ నియమాలు పాటించాలి.","6. మంచి ఆహారం తింటేనే బలం వస్తుంది; బలవంతుడే దేశానికి ఉపయోగపడతాడు."]],["సృజనాత్మకత / ప్రశంస / భాషాంశాలు (పుట 29)",["గేయం: వందనం వందనం – నేతాజీకి వందనం / వందనం వందనం – వీర సైనికులకు వందనం / వందనం వందనం – రైతన్నకు వందనం.","ప్రశంస: “సైనికులారా! మీరు మన దేశాన్ని రాత్రింబవళ్ళు కాపాడుతున్నారు. మీకు సెల్యూట్!”","భాషాంశాలు: 6 వాక్యాల్లోనూ చివర ( ? ) గుర్తు ఉంది – చుట్టాలి."]],["నేనేమి నేర్చుకున్నాను? (పుట 33)",["1. ఇ) మనుషులోయ్","2. పంటలు, దేశాలు","3. ఆ) కలిసిమెలిసి ఉండటం","4. i) చల్లని నీడ, తీయని పండ్లు ఇస్తుంది; పక్షులు గూళ్ళు కట్టుకుంటాయి. ii) ద్విత్వం: గట్టి, పెద్ద, చెట్టు, పిల్లలు | సంయుక్తం: శ్రమ, పక్షులు, ఇష్టం","5–7. పిల్లల సొంత జవాబులు."]]]},{"id":"te4","no":4,"t":"పరివర్తన","m":[9],"ty":"కథ","th":"పిల్లల స్వభావం","by":"వేంకట పార్వతీశ కవులు","sum":"రాముకు ఆటలంటే ఇష్టం, చదువు అంటే అశ్రద్ధ. ఒకరోజు బడికి వెళ్ళకుండా మామిడి తోటలోకి వెళ్ళాడు. కాకిని, తేనెటీగను, చీమను ఆడుకుందామని పిలిచాడు. కాకి వానాకాలం రాకముందే గూడు కట్టుకుంటున్నానంది; తేనెటీగ పూలు వాడకముందే తేనె సేకరిస్తున్నానంది; చీమ రాబోయే వానాకాలానికి గింజలు సేకరిస్తున్నానంది. “అవన్నీ తమ పనుల్లో ఉన్నాయి, నేను కూడా బడికి వెళ్ళి చదువుకోవాలి” అని రాము గ్రహించి వెంటనే బడికి వెళ్ళాడు. ఇదే రాములో వచ్చిన పరివర్తన (మార్పు).","pts":["కవులు: వేంకట పార్వతీశ కవులు – బాలాంత్రపు వేంకటరావు (1880–1955), ఓలేటి పార్వతీశం (1882–1970) – జంట కవులు.","రాము – బద్ధకం, ఆటలంటే ఇష్టం; చివరికి చదువు విలువ తెలుసుకున్నాడు.","కాకి – గూడు; తేనెటీగ – తేనె; చీమ – గింజలు. అన్నీ “రాబోయే కాలం” కోసం ముందే కష్టపడుతున్నాయి.","నీతి: సమయాన్ని వృథా చేయకూడదు; ఎవరి పని వారు సమయానికి చేయాలి.","గొంగళి పురుగు → సీతాకోకచిలుక: గుడ్లు → గొంగళి పురుగు (లార్వా) → ప్యూపా → సీతాకోకచిలుక.","చదువుదాం: “కాగితం పువ్వు” – నీతి: కంటికి కనబడే రూపం కంటే సహజమైన మంచితనం గొప్పది."],"w":[["పరివర్తన","మార్పు"],["చిందరవందర","క్రమపద్ధతిలో లేకపోవడం"],["ఆహ్లాదంగా","సంతోషంగా"],["ఆసక్తిగా","ఇష్టంగా"],["ఆత్మీయంగా","ప్రేమగా"],["చిన్నబుచ్చుకొను","నిరాశపడు"],["శ్రమించు","కష్టపడు"],["వ్యర్థంగా","పనికిరాకుండా"]],"gr":{"t":"నామవాచకం – సర్వనామం • అనుకరణ పదాలు","p":["మనుషులు, జంతువులు, పక్షులు, వస్తువులు, ప్రదేశాల పేర్లు – నామవాచకాలు. ఉదా: రఘు, సింహం, పావురం, జామ, అమరావతి.","నామవాచకాలకు బదులుగా వాడే పదాలు – సర్వనామాలు: అతడు, ఆమె, అది, వారు, అవి.","అనుకరణ పదాలు: గలగల, కిలకిల, టపటప, గణగణ."]},"qa":[["రాముతో ఆడుకోవడానికి ఎవరెవరు రానన్నారు?","కాకి, తేనెటీగ, చీమ."],["కాకి ఎందుకు ఆడుకోలేనంది?","రానున్నది వానాకాలం, గూడు కట్టుకుంటున్నానని."],["చీమ ఏమి చేస్తోంది?","రాబోయే వానాకాలం కోసం గింజలు సేకరిస్తోంది."],["రాము ఏమి గ్రహించాడు?","అన్నీ తమ పనుల్లో ఉన్నాయి; తాను కూడా బడికి వెళ్ళి చదువుకోవాలని."]],"act":"కాకి – నక్క కథను ఖాళీలు నింపి పూర్తి చేయండి. మీ పాఠశాల వివరాలు సేకరించి రాయండి. సీతాకోకచిలుక జీవిత చక్రం బొమ్మ గీయండి.","kn":"గొంగళి పురుగును “లార్వా” అంటారు. అది ఆకుల కింద ప్యూపా (గూడు) తయారుచేసుకొని దానిలోంచి సీతాకోకచిలుకగా బయటకు వస్తుంది.","qz":[["“పరివర్తన” అంటే?","మార్పు","ఆట","చదువు","కోపం"],["రాము బడికి వెళ్ళకుండా ఎక్కడికి వెళ్ళాడు?","మామిడి తోటకు","నది దగ్గరికి","సినిమాకు","బజారుకు"],["కాకి ఏమి చేస్తోంది?","గూడు కట్టుకుంటోంది","తేనె సేకరిస్తోంది","గింజలు సేకరిస్తోంది","పాట పాడుతోంది"],["తేనెటీగ ఏమి చేస్తోంది?","పూల నుండి తేనె సేకరిస్తోంది","గూడు కట్టుకుంటోంది","గింజలు మోస్తోంది","నిద్రపోతోంది"],["చీమ ఏ కాలం కోసం గింజలు దాస్తోంది?","వానాకాలం","వేసవికాలం","వసంతకాలం","శరదృతువు"],["“శ్రమించు” అర్థం?","కష్టపడు","ఆలస్యం","నిదానం","బద్ధకం"],["“చిందరవందర” అంటే?","క్రమపద్ధతిలో లేకపోవడం","చక్కగా సర్దడం","సంతోషంగా","ప్రేమగా"],["“కాకి, కోయిల, పాము, పిచ్చుక” – వేరుగా ఉన్నది?","పాము","కాకి","కోయిల","పిచ్చుక"],["కిందివాటిలో సర్వనామం?","అతడు","రఘు","సింహం","జామ"],["కిందివాటిలో అనుకరణ పదం?","గలగల","మామిడి","బడి","చీమ"],["పాఠం కవులు?","వేంకట పార్వతీశ కవులు","తిరుపతి వేంకట కవులు","గురజాడ","అన్నమయ్య"],["సీతాకోకచిలుకగా మారే ముందు దశ?","ప్యూపా","గుడ్డు","చీమ","పువ్వు"],["ఈ పాఠం నీతి?","సమయాన్ని వృథా చేయకూడదు","ఎప్పుడూ ఆడుకోవాలి","బడికి వెళ్ళనక్కర్లేదు","పక్షులను పట్టుకోవాలి"]],"wb":{"pg":"29–37","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":35,"ws":["సాధనపత్రం 1–2: చదవడం (సతీష్ కథ, ఎవరు ఎవరితో అన్నారు, పడవ గేయం, సంభాషణకు ప్రశ్నలు)","సాధనపత్రం 3–4: పదజాలం (అక్షరాలు, అంత్యాక్షరి, అనుకరణ పదాల జతలు, వేరుగా ఉన్నది)","సాధనపత్రం 5: స్వీయరచన","సాధనపత్రం 6–7: భాషాంశాలు – విరామ చిహ్నాలు, నామవాచకం, సర్వనామం","సాధనపత్రం 8: సృజనాత్మకత (నక్క – కొంగ కథ, సీతాకోకచిలుక)","నేనేమి నేర్చుకున్నాను?"],"mis":"నామవాచకం = పేరు (రఘు, కుక్క, పాఠశాల); సర్వనామం = పేరుకు బదులు వచ్చే పదం (అతడు, ఆమె, అది, వారు). “నీరు” నామవాచకం, సర్వనామం కాదు.","qz":[["సతీష్ మొదట సమయాన్ని ఎలా గడిపేవాడు?","టి.వి. చూస్తూ","చదువుతూ","సెల్‌ఫోన్ చూస్తూ","ఆడుకుంటూ"],["“అశ్రద్ధ” వ్యతిరేకం?","శ్రద్ధ","అలసట","నిద్ర","భయం"],["“అయ్యో! బాబు. రానున్నది వానాకాలం. అసలే నాకు గూడు లేదు” అన్నది?","కాకి","చీమ","తేనెటీగ","అమ్మ"],["పడవ ఉయ్యాలగా మారినప్పుడు?","ఊగింది","తేలింది","ఆడింది","మునిగింది"],["“పకపక” కు జత?","నవ్వడం","ఏడవడం","నడవడం","సెలయేరు"],["“బొద్దింక, చీమ, ఈగ, ఏనుగు” – వేరుగా ఉన్నది?","ఏనుగు","బొద్దింక","చీమ","ఈగ"],["“కుక్క, పిల్లి, దోమ, గేదె” – వేరుగా ఉన్నది?","దోమ","కుక్క","పిల్లి","గేదె"],["కిందివాటిలో నామవాచకం కానిది?","వారు","పుస్తకం","అమరావతి","సంచి"],["“సూరయ్య పొలానికి వెళ్ళాడు. ___ అరక దున్నాడు.”","అతడు","ఆమె","అది","అవి"],["కిందివాటిలో సర్వనామం కానిది?","నీరు","నేను","మీరు","వారు"],["“చిన్నబుచ్చుకుంది” అర్థం?","నిరాశపడింది","సంతోషపడింది","మొహమాటపడింది","ఆలోచించింది"],["సైనికులు చేసే పని?","దేశాన్ని కాపాడటం","వైద్యం చేయడం","పాఠాలు చెప్పడం","వ్యవసాయం"]]},"tg":[["చిత్రం చూడండి – ఆలోచించి మాట్లాడండి (పుట 34)",["1. తాడు లాగుట, తొక్కుడుబిళ్ళ, కళ్ళగంతలు (దాగుడుమూతలు), రింగాట, ఫుట్‌బాల్, ఉయ్యాల – పిల్లలు ఆడుతున్నారు.","2. కబడ్డీ, ఖో-ఖో, గోళీలు, చెడుగుడు, క్రికెట్, చదరంగం."]],["ఇవి చేయండి – వినడం, ఆలోచించి మాట్లాడటం (పుట 37)",["1. పిల్లలు కథను సొంత మాటల్లో చెప్పాలి.","2. కాకి, తేనెటీగ, చీమలతో మాట్లాడాడు.","3. అవి రాబోయే వానాకాలం కోసం తమ పనుల్లో (గూడు, తేనె, గింజలు) ఉన్నాయి.","4. “బడి అయ్యాక ఆడుకుందాం” అని చెప్పి బడికి వెళ్తాను."]],["చదవడం – వ్యక్తపరచడం (పుట 37–38)",["అ) 1. అ) చీమ, కాకి","2. రాబోయే వానాకాలం కోసం.","3. కష్టపడు","4. అవన్నీ తమ పని చేస్తున్నాయి; నేను కూడా బడికి వెళ్ళి చదువుకోవాలి అని ఆలోచించి ఉంటాడు.","ఆ) అనుకరణ పదాలు: గలగల, కిలకిల, టపటప – ఇంకా: పకపక, గడగడ, చకచక, బుడబుడ, మిలమిల"]],["పదజాలం / స్వీయరచన (పుట 38–39)",["ఇ) 1. పాము  2. ఏనుగు  3. దోమ  4. గులాబీ","1. కాకి  2. గులాబి, మల్లె  3. సమయానికి పని చేయాలి; కాలం వృథా చేయకూడదు.","4. నీటి గలగలలు, పక్షుల కిలకిలలతో పచ్చగా, ఆహ్లాదంగా ఉంది.","5. గడిచిన కాలం తిరిగి రాదు.","6. రోజూ బడికి వెళ్ళి శ్రద్ధగా చదువుకుంటాను."]],["సృజనాత్మకత / ప్రశంస (పుట 39)",["కథ: ఒకరోజు కాకికి మాంసం (రొట్టె) ముక్క దొరికింది. అది నక్క చూసి, ఆ ముక్కను తినాలనుకుంది. “కాకీ! నీవు బాగా పాడతావు” అన్నది. కాకి పొంగిపోయి “కావ్” అన్నది. కాకి నోటిలో ముక్క కింద పడింది. నక్క దాన్ని తీసుకొని చక్కా పోయింది.","ప్రశంస: “చదువుతో పాటు మంచి నడవడిక నేర్చుకుంటున్నారు, మీకు అభినందనలు!”"]],["భాషాంశాలు (పుట 40)",["అ) మనుషులు: రఘు, వర్షిణి, ఆయేషా, ఆసిఫ్, మీరా, హర్షిత, మేరీ, సంతోష్ | జంతువులు: సింహం, పులి, ఏనుగు, జిరాఫీ, కోతి | పక్షులు: పావురం, నెమలి, రామచిలుక, నిప్పుకోడి | పండ్లు: జామ, బత్తాయి, అరటి | సర్వనామాలు: వాళ్ళు, వారు, అవి, వాటిని","ఆ) 1. కాకి, తేనెటీగ, చీమ వాటి పనిలో అవి ఉన్నాయి.  2. రవి బడికి వెళ్ళాడు. అతడు బాగా చదువుతాడు."]],["నేనేమి నేర్చుకున్నాను? (పుట 44)",["1. ఇ) కలిసి","2. గలగల, గణగణ","3. అ) నీ పేరు ఏమిటి? ఎవరు?  ఆ) నువ్వు ఊరికి ఎప్పుడు వెళ్తావు?","4. i) చెట్లు సూర్యరశ్మితో ఆహారం తయారుచేసుకుంటాయి.  ii) సూర్యుడు వెలుతురు, వేడి ఇస్తాడు; అతను లేకపోతే చెట్లు ఆహారం తయారుచేసుకోలేవు.","5. ఒకరోజు కాకికి రొట్టె ముక్క దొరికింది. … కాకి నోటిలో ముక్క కింద పడింది. నక్క దాన్ని తీసుకొని చక్కా పోయింది.","7–8. పిల్లల సొంత జవాబులు."]]]},{"id":"te5","no":5,"t":"సత్యమహిమ","m":[10],"ty":"గేయకథ","th":"నైతిక విలువలు","by":"అవధాని రమేష్ (“గుజ్జనగూళ్ళు” నుండి)","sum":"ఒక పల్లెలో నిజాయితీగల పేదవాడు కట్టెలు కొట్టి అమ్ముకొని జీవించేవాడు. ఒకరోజు నది ఒడ్డున చెట్టు కొడుతుంటే గొడ్డలి జారి నీటిలో పడింది. “పిల్లలకు అన్నం ఎలా పెట్టాలి?” అని బాధపడ్డాడు. నదీదేవత ప్రత్యక్షమై బంగారు గొడ్డలి చూపి “ఇది నీదా?” అని అడిగింది. “కాదమ్మా” అన్నాడు. వెండి గొడ్డలి చూపింది – “అదీ నాది కాదు” అన్నాడు. ఇనుప గొడ్డలి చూపగానే “ఇదే నాది” అన్నాడు. అతని నిజాయితీకి మెచ్చి దేవత మూడు గొడ్డళ్ళూ బహుమతిగా ఇచ్చి దీవించింది.","pts":["కవి: అవధాని రమేష్ (20వ శతాబ్దం) – కర్నూలు జిల్లా అవుకు అగ్రహారం; రచనలు “కాసులపేరు”, “ప్రతీకారం”, “మూడు మంచి కథలు”; గేయకథ “గుజ్జనగూళ్ళు” నుండి.","పేదవాడు – అకలంక చరితుడు (మచ్చలేని ప్రవర్తన), సత్యవ్రతం పాటించేవాడు.","గొడ్డళ్ళు: బంగారు → వెండి → ఇనుప (తనది). దేవత మూడూ ఇచ్చింది.","నీతి: నిజాయితీకి ఎప్పుడూ మంచి ఫలితం వస్తుంది – సత్యమే గెలుస్తుంది.","చదవడం: ఆవు – పులి కథ (సత్యసంధత); పాడుదాం: “పిల్లల్లారా – పాపల్లారా” – దాశరథి కృష్ణమాచార్య.","చదువుదాం: “చిన్ననాటి దుర్గాబాయి” – టికెట్ లేని నెహ్రూను సభలోకి అనుమతించలేదు (కర్తవ్య నిష్ఠ)."],"w":[["మహిమ","గొప్పతనం"],["అకలంక","మచ్చలేని"],["సత్యవ్రతంబు","ఎల్లవేళలా నిజం చెప్పే వ్రతం"],["నిత్యంబు","ఎల్లప్పుడు"],["తెన్నులు చూచి","ఎదురు చూసి"],["మొగంబు","ముఖము"],["ఆర్తి","దుఃఖం"],["దీనత","దారిద్ర్యం"],["కరుణ","దయ, జాలి"],["మిరుమిట్లు","మెరుగులు"],["తిలకించి","చూసి"],["మది","మనసు"],["బహుమానం","కానుక"],["వన్నె","అందం, రంగు"]],"gr":{"t":"క్రియాపదాలు – జరిగిన / జరుగుతున్న / జరగబోయే పని","p":["పనులు జరగడాన్ని తెలిపే పదాలు – క్రియాపదాలు: వెళ్ళారు, కోసారు, తెచ్చారు, ఇచ్చారు.","జరిగిన పని: తెచ్చాడు, వచ్చారు. జరుగుతున్న పని: ఆడుతున్నాడు, పాడుతున్నది. జరగబోయే పని: వెళ్తాను, జరుగుతాయి.","బహువచనం: చెట్టు – చెట్లు, దేవత – దేవతలు, నది – నదులు, పిల్లవాడు – పిల్లలు."]},"qa":[["పేదవాడు ఎలా జీవించేవాడు?","కట్టెలు కొట్టి అమ్ముకొని, నిజాయితీగా జీవించేవాడు."],["పేదవాడు ఎందుకు బాధపడ్డాడు?","గొడ్డలి నీటిలో పడిపోయింది; పిల్లలకు ఆహారం ఎలా తేవాలని బాధపడ్డాడు."],["నదీదేవత మొదట ఏ గొడ్డలి చూపింది?","బంగారు గొడ్డలి."],["నదీదేవత ఎందుకు మెచ్చుకుంది?","అతని నిజాయితీకి (తనది కానిది ఆశించనందుకు)."]],"act":"విజయ్ – తాత కథను పొడిగించండి. కథల పుస్తకంలోని క్రియాపదాలతో వాక్యాలు రాయండి. అడవులు మనకు ఎలా ఉపయోగపడతాయో తెలుసుకోండి.","kn":"అడవులు కుంకుడుకాయలు, తేనె, కరక్కాయలు, మూలికలు, ఔషధాలు ఇస్తాయి; వర్షాలకు కారణమవుతాయి; నేల కోతను ఆపుతాయి.","qz":[["“సత్యమహిమ” గేయకథ రచయిత?","అవధాని రమేష్","గురజాడ","అన్నమయ్య","దాశరథి"],["పేదవాడి వృత్తి?","కట్టెలు కొట్టడం","చేపలు పట్టడం","వ్యవసాయం","వ్యాపారం"],["గొడ్డలి ఎక్కడ పడింది?","నదిలో","బావిలో","చెరువులో","గోతిలో"],["నదీదేవత మొదట చూపిన గొడ్డలి?","బంగారు","వెండి","ఇనుప","రాగి"],["పేదవాడి సొంత గొడ్డలి?","ఇనుప గొడ్డలి","బంగారు గొడ్డలి","వెండి గొడ్డలి","కర్ర గొడ్డలి"],["నదీదేవత చివరకు ఇచ్చినవి?","మూడు గొడ్డళ్ళు","ఇనుప గొడ్డలి మాత్రమే","బంగారు గొడ్డలి మాత్రమే","డబ్బులు"],["“అకలంక” అంటే?","మచ్చలేని","చెడ్డ","పేద","ధనిక"],["“బహుమానం” అర్థం?","కానుక","అందం","బంగారం","పొగడ్త"],["“కరుణ” అర్థం?","దయ","కోపం","దుఃఖం","భయం"],["“అది నాది కాదమ్మా” అని పేదవాడు అనడం దేన్ని చూపిస్తుంది?","నిజాయితీ","అత్యాశ","భయం","బద్ధకం"],["“తెచ్చాడు” ఏ కాలం క్రియ?","జరిగిన పని","జరుగుతున్న పని","జరగబోయే పని","క్రియ కాదు"],["టికెట్ లేని నెహ్రూను ఆపిన బాలిక?","దుర్గాబాయి దేశ్‌ముఖ్","సరోజినీ నాయుడు","ఝాన్సీ లక్ష్మీబాయి","మల్లీశ్వరి"],["“నది” బహువచనం?","నదులు","నదిలు","నదీలు","నదాలు"]],"wb":{"pg":"38–46","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":44,"ws":["సాధనపత్రం 1–2: చదవడం (వీరయ్య నిజాయితీ, గేయ పాదాలు సరిచేయడం, పిచ్చుక కథ, చందమామ గేయం)","సాధనపత్రం 3–4: పదజాలం (అక్షరాలు, రంగులు, అర్థాలు, జంటపదాలు, గళ్ళ నుడికట్టు)","సాధనపత్రం 5: స్వీయరచన","సాధనపత్రం 6–7: భాషాంశాలు – క్రియాపదాలు (జరిగిన/జరుగుతున్న/జరగబోయే)","సాధనపత్రం 8: సృజనాత్మకత","నేనేమి నేర్చుకున్నాను?","అపోహలు (Misconception) పోస్టర్లు – పుట 47–50"],"mis":"క్రియ = పని. “వెళ్ళింది” క్రియ; “సీత, అడవికి, రాముడు” క్రియలు కావు. కాలం గుర్తించాలంటే: నిన్న → జరిగిన పని, ఇప్పుడు → జరుగుతున్న పని, రేపు → జరగబోయే పని.","qz":[["“చేసిన తప్పు తెలుసుకొని…” – “తప్పు” వ్యతిరేకం?","ఒప్పు","మంచి","న్యాయం","ఆనందం"],["వీరయ్య ఎక్కడ పనిచేసేవాడు?","ఒక వ్యాపారి వద్ద","పొలంలో","బడిలో","అడవిలో"],["“సీత, రామునితో కలిసి అడవికి వెళ్ళింది” – క్రియాపదం?","వెళ్ళింది","అడవికి","సీత","రాముడు"],["“నాన్న నిన్న ఢిల్లీ ___”","వెళ్ళాడు","వెళ్తాడు","వెళ్ళు","వెళ్తున్నాడు"],["“పండు మిరప” రంగు?","ఎరుపు","పసుపు","తెలుపు","ఆకుపచ్చ"],["“బహుమానం” అర్థం?","కానుక","అందం","బంగారం","పొగడ్త"],["“అబద్ధం” వ్యతిరేకం?","నిజం","తప్పు","మోసం","కోపం"],["“రేపు నేను తాతయ్యతో ఊరికి వెళ్తాను” – ఏ పని?","జరగబోయే పని","జరిగిన పని","జరుగుతున్న పని","క్రియ లేదు"],["“సిరి నృత్యం చేస్తున్నది” – ఏ పని?","జరుగుతున్న పని","జరిగిన పని","జరగబోయే పని","నామవాచకం"],["“తిలకించి” అర్థం?","చూసి","అడిగి","చదివి","అరచి"],["“చలికి శరీరము ___ వణికెను” – సరైన పదం?","గజగజ","గడగడ","గలగల","గుటగుట"],["పంటలు పండించేవాడు?","రైతు","సైనికుడు","వైద్యుడు","వ్యాపారి"]]},"tg":[["చిత్రం చూడండి – ఆలోచించి మాట్లాడండి (పుట 45)",["1. పాఠశాల, జెండా, తాడు, ఉపాధ్యాయురాలు, పిల్లలు ఉన్నారు.","2. విద్యార్థులు, ఉపాధ్యాయురాలు ఉన్నారు.","3. పిల్లలు తాడు లాగే ఆట (టగ్ ఆఫ్ వార్) ఆడుతున్నారు.","4. “టీచర్! ఆట స్థలంలో ఈ పర్సు/వస్తువు దొరికింది, తీసుకోండి” అని ఇస్తున్నాడు – నిజాయితీ."]],["ఇవి చేయండి – వినడం, ఆలోచించి మాట్లాడటం (పుట 49)",["1. గేయాన్ని రాగయుక్తంగా పాడించాలి.","2. బంగారు, వెండి, ఇనుప గొడ్డళ్ళు.","3. అది తనది కాదు; తనది కానిది తీసుకోకూడదని.","4. నా ఇనుప గొడ్డలి మాత్రమే తీసుకుంటాను – నిజాయితీ ముఖ్యం.","5. బంగారు, వెండి గొడ్డళ్ళు (తన ఇనుప గొడ్డలితో పాటు)."]],["చదవడం – వ్యక్తపరచడం (పుట 49)",["ఖాళీలు: మేత, పంజా, లేగదూడ, పాలిచ్చి, మెలగాలో, తల్లిని, సత్యసంధత","1. ఆ) అడవిలో","2. తన లేగదూడకు పాలిచ్చి, బుద్ధులు నేర్పి తిరిగి వస్తానని చెప్పింది.","3. ఆవు సత్యసంధతకు (మాట నిలబెట్టుకున్నందుకు) మెచ్చి వదిలిపెట్టింది."]],["పదజాలం / స్వీయరచన (పుట 50)",["ఆ) బహుమానం – బహుమానాలు, దేవత – దేవతలు, పిల్లవాడు – పిల్లలు, నది – నదులు (వాక్యాలు పిల్లలు రాయాలి)","1. “ఇది నీదేనేమో చూడు” అని పలికింది.","2. బంగారు, వెండి గొడ్డళ్ళు.","3. మచ్చలేని ప్రవర్తన, నిజాయితీ, కష్టజీవి, ఆశ లేనివాడు.","4. గొడ్డలి నీటిలో పడిపోయినందుకు.","5–6. పిల్లల సొంత జవాబులు."]],["సృజనాత్మకత / ప్రశంస / భాషాంశాలు (పుట 51–52)",["సృజనాత్మకత: విజయ్ తాతకు తిరిగి వెళ్ళి గొడుగు ఇచ్చాడు. తాత “చల్లగా ఉండు నాయనా” అని దీవించాడు.","ప్రశంస: “కార్తీక్! దొరికిన పుస్తకాన్ని తిరిగి ఇచ్చి నిజాయితీ చూపావు – శభాష్!”","క్రియాపదాలు: ఆడారు, రాసింది, చేసింది, గీసాడు, పాడాడు.","ఖాళీలు: గీత కవితలు రాసింది, హర్షిత చిత్రాలు గీసింది, చంద్ర అన్నం తిన్నాడు, రాబర్ట్ సైకిల్ తొక్కాడు, సలీమ్ పాటలు పాడాడు."]],["నేనేమి నేర్చుకున్నాను? (పుట 55)",["1. ఈ) అన్నీ","2. వెలవెలబోవు = కాంతి తగ్గు, కళ తప్పు","3. అతని నిజాయితీకి (తనది కానిది ఆశించనందుకు).","4. i) మిత్రుడికి సాయం చేయాలనే మంచి మనసు.  ii) సాయం చేయడం, కలిసి ఉండటం, మంచి గుణాలు నేర్పడం.","5. 1. గొడ్డలి నీటిలో పడిపోయింది.  2. అతడు నిజం చెప్పాడు.","6–9. పిల్లల సొంత జవాబులు (9. దేవత అతని గొడ్డలి కూడా ఇవ్వకుండా వెళ్ళిపోయేది)."]]]}],"eng":[{"id":"en1","no":1,"t":"Three Butterflies","m":[7],"ty":"Story","th":"Friendship & Unity","by":"Blossoms-4, Unit 1","sum":"Three butterflies – white, red and yellow – lived in a garden as friends. One afternoon it started raining and they got wet. The sunflower agreed to shelter only the red and yellow ones, not the white one. The white lily agreed to shelter only the white one. Each time the butterflies refused, saying they would not send away a friend. The Sun, pleased with their love and unity, chased the clouds away, stopped the rain and dried their wings. They danced happily till evening.","te":"తెలుపు, ఎరుపు, పసుపు రంగుల మూడు సీతాకోకచిలుకలు స్నేహితులు. వర్షంలో తడిసి ఆశ్రయం కోసం వెతికాయి. పొద్దుతిరుగుడు పువ్వు ఎరుపు, పసుపు వాటికే చోటిస్తానంది; తెల్ల కలువ తెల్లదానికే అంది. “స్నేహితులను వదిలి మేము ఉండం” అని అవి నిరాకరించాయి. వాటి ఐకమత్యం చూసి సూర్యుడు మేఘాలను తరిమి, వాటి రెక్కలు ఆరబెట్టాడు. నీతి: నిజమైన స్నేహితులు కష్టంలోనూ కలిసే ఉంటారు.","pts":["Characters: white, red and yellow butterflies, the sunflower, the white lily, the Sun.","Sunflower – shelter only for red & yellow; White lily – shelter only for white. Butterflies refused both.","The Sun chased away the clouds and dried their wings – reward for unity.","Plurals: -s (clouds), -es (benches, boxes), -ies (families, butterflies).","Material nouns: gold, silver, wood, iron, cotton, silk, milk, oil.","Polite requests: “Can I …?” / “May I …?” – Yes, you may/can. No, you may not/can’t.","Punctuation: full stop (.), comma (,), question mark (?), capital letters."],"w":[["nectar","a sweet liquid in flowers (మకరందం)"],["shelter","a place that protects from bad weather (ఆశ్రయం)"],["curiously","interestingly"],["dismay","unhappiness and disappointment"],["pebbles","small stones (గులకరాళ్ళు)"],["chased","ran after to catch (తరిమాడు)"],["drenched","completely wet"]],"gr":{"t":"Plurals (-s/-es/-ies) • Material Nouns • Can / May • Punctuation","p":["Add -s: cloud – clouds; -es after s, sh, ch, x: bench – benches, box – boxes; consonant + y → -ies: family – families.","Material Noun: the name of a metal or substance from which things are made – gold, wood, cotton, iron, wool.","Seeking permission: “May I come in?” Giving: “Yes, you may.” Refusing: “No, you may not.”","Capital letter at the beginning of a sentence, for names and for “I”; full stop at the end; question mark after a question."]},"qa":[["Why did the butterflies stop playing?","Because it grew dark, a cold wind blew and it started to rain."],["Why was it difficult for them to fly?","Their wings were wet in the rain."],["“We won’t stay here.” Why did the butterflies say so?","Because the flower would not shelter all of them; they did not want to send away their friend."],["How did the Sun help the butterflies?","He chased the clouds away, stopped the rain and dried their wings."]],"act":"Write the plurals of cloud, bench, family, petal, class, city, wing, brush, story. Underline material nouns: “Silver is used to make jewellery.” Play the language game “Can you do this?” with dice.","kn":"Butterfly life cycle: egg → caterpillar → pupa → butterfly. “Good things take time to happen.”","qz":[["How many butterflies lived in the garden?","Three","Two","Four","Five"],["What colours were the butterflies?","White, red and yellow","Blue, red and green","Black, white and pink","Orange, red and blue"],["Which flower would not let the white butterfly in?","The sunflower","The white lily","The rose","The lotus"],["Which flower offered shelter only to the white butterfly?","The white lily","The sunflower","The jasmine","The marigold"],["Who chased the clouds away?","The Sun","The Moon","The wind","The sunflower"],["Butterflies suck ___ from flowers.","nectar","water","colour","petals"],["The rain came down like ___ on the butterflies.","pebbles","flowers","balls","marbles"],["The meaning of “shelter” is ___.","a safe place to stay","a sweet liquid","small stones","a cold wind"],["The plural of “story” is ___.","stories","storys","storyes","storeys"],["The plural of “bench” is ___.","benches","benchs","benchies","bench"],["Which is a material noun? “The gate is made of iron.”","iron","gate","made","strong"],["Choose the polite request.","May I drink water, please?","Give me water.","I drink water.","Water I drink?"],["Which sentence is written correctly?","Rani and I are playing in the park.","rani and i are playing in the park.","Rani and I are playing in the park?","rani and i are playing in the park"],["What does the story teach us?","True friends stay together in good and bad times.","Never play in the rain.","Flowers are selfish.","The Sun is hot."]],"wb":{"pg":"52–64","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":58,"ws":["1.1–1.3 Passage questions, vocabulary, spelling, odd one out, sequencing, match, true/false","1.4 Plurals (-s/-es/-ies) and antonyms","1.5 Material nouns","1.6 Polite requests – Can / May","1.7–1.8 Reading comprehension (unseen passages)","1.9 Writing – about friends, badminton talk, rainy day","1.10 My Self Reflections","Let us Practise answers (ruled pages)"],"mis":"“May” is used to ask permission politely (formal); “Can” shows ability or informal permission. ✗ “Can I come in, sir?” (to a teacher) ✓ “May I come in, sir?”","qz":[["Why did the butterflies look for shelter?","It started raining heavily.","They were tired of flying.","It became very hot.","It was night time."],["What quality did the butterflies show?","unity and friendship","pride","greed","anger"],["“They needed shelter from the rain.” shelter means ___.","protection","food","sleep","water"],["Choose the correct spelling.","nectar","necter","nactar","nectre"],["Odd one out: red, blue, yellow, huge","huge","red","blue","yellow"],["Fill in: “She picked three ___.” (lily)","lilies","lilys","lilyes","lily"],["Antonym of “wet” is ___.","dry","cold","light","near"],["Circle the material noun: “The shoes are made of leather.”","leather","shoes","made","are"],["Fill in: “___ I use your pencil, please?”","May","Must","Will","Do"],["Refusing permission:","No, you may not.","Yes, you may.","May I go?","Can you run?"],["In the passage, where did the boy sleep on the rainy day?","in his mother’s lap","outside the house","on the roof","in the school"],["Correct alphabetical order:","behind, difficult, night, still","night, still, difficult, behind","still, night, behind, difficult","difficult, behind, still, night"]]},"tg":[["Activity 1 – Look at the picture (Text p.59)",["1. Children playing in the rain; a girl holding an umbrella, a boy with a raincoat, paper boats.","2. Yes, I like to play in the rain (free answer).","3. An umbrella / a raincoat.","4. I would share my umbrella with my friends."]],["Activity 2 – Answer the questions (Text p.62)",["1. It grew dark, a cold wind blew and it started raining.","2. Their wings got wet in the rain.","3. They did not want to leave their friend alone – the flowers offered shelter only to some.","4. The Sun chased the clouds away and dried their wings.","5. I would give shelter to all three butterflies.","6. I feel happy when I help someone in need.","Choose: 1. A) garden  2. C) nectar  3. C) small stones (pebbles)  4. B) Sun  5. B) The Sunflower"]],["Activity 3 & 4 – Plurals (Text p.64)",["-s: petals, wings, pebbles, flowers | -es: classes, brushes, dresses, buses | -ies: cities, stories, countries, butterflies","Crossword: gardens, lilies, clouds, nights, boxes, poems, friends, schools"]],["Activity 5 – Material Nouns (Text p.65)",["1. Silver  2. diamond  3. oil  4. silk  5. milk  6. wood  7. Iron  8. cotton"]],["Activity 6 – Punctuation (Text p.68)",["Rani, Mary, Rajesh, Basha and Rehana are playing cricket. “Don’t you go to school?” asked an old man. “Today is Sunday. Sunday is a holiday,” they said."]],["Activity 7 – Conversation (Text p.68–69)",["Butterflies: Dear Cuckoo, we know that you are a good singer. We want to learn singing. Can you teach us to sing?","Cuckoo: With pleasure, dear Butterflies, I can teach you to sing.","Butterflies: Dear Fish, we know that you are a good swimmer. Can you teach us to swim?","Fish: Sorry, dear Butterflies, I can’t. You can’t live in water!"]],["Activity 8 – Butterfly & Caterpillar (Text p.70)",["1. C) caterpillar  2. B) butterfly is once a caterpillar.  3. B) changing caterpillar into butterfly  4. A) butterfly and caterpillar"]],["Let us Practise (Text p.74–75)",["Answers are given in the workbook answer pages (Unit 1, ruled pages): 1. B) completely wet 2. different 3. Pebble 4. b, a, d, c 6. B) butterflies 7. D) Iron 8. C 9. A) can/cannot 10. B 11. B) The Sunflower …"]]]},{"id":"en2","no":2,"t":"Major Dhyan Chand","m":[8],"ty":"Biography","th":"Sports & Patriotism","by":"Adapted from Sanjay Dudhane • Poem: Fit Body, Fit Mind, Fit Nation","sum":"Dhyan Singh was a soldier who practised hockey at night in the moonlight, so his coach called him “Dhyan Chand” (Chand = Moon). On 15 August 1936, in the Berlin Olympics final, India played against the host Germany on a wet ground. Roop Singh scored the first goal. Dhyan Chand, the captain, removed his spiked shoes and played barefoot. Though hurt by the German goalkeeper, he returned and scored. India won the gold for the third time in a row – a hat-trick. He refused the German ruler’s offer. His birthday, 29 August, is National Sports Day.","te":"ధ్యాన్ సింగ్ సైనికుడు; పగలు విధుల వల్ల రాత్రి వెన్నెల్లో హాకీ సాధన చేసేవాడు – అందుకే “ధ్యాన్ చంద్” (చంద్ = చంద్రుడు). 1936 బెర్లిన్ ఒలింపిక్స్ ఫైనల్‌లో జర్మనీపై భారత్ గెలిచి వరుసగా మూడోసారి బంగారు పతకం (హ్యాట్రిక్) సాధించింది. జర్మనీ పాలకుడి ఆఫర్‌ను ఆయన తిరస్కరించారు. ఆయన పుట్టినరోజు ఆగస్టు 29 – జాతీయ క్రీడా దినోత్సవం.","pts":["Real name: Dhyan Singh; a soldier in the Indian Army; practised in moonlight → “Chand”.","1936 Berlin Olympics final: India vs Germany (hosts), 15 August 1936, wet ground, about 40,000 spectators.","First goal: Roop Singh (32nd minute). Dhyan Chand played barefoot and scored the last goal.","India – third Olympic hockey gold in a row (hat-trick). Hockey – our national sport.","29 August – National Sports Day; National Stadium in Delhi is named after him; called “Wizard of Hockey”.","Irregular plurals: man–men, woman–women, foot–feet, tooth–teeth, goose–geese, mouse–mice, child–children.","Pronouns: he, she, it, we, they, you, I. Sympathy: “I am sorry.”, “Don’t worry.”"],"w":[["victory","win / success"],["postpone","put off to a later time"],["barefoot","without wearing anything on the feet"],["pounced","jumped"],["spectators","people who watch a game"],["dribbled","pushed the ball along with the stick"],["legacy","something special from the past"]],"gr":{"t":"Irregular Plurals • Pronouns • Expressing sympathy","p":["Some nouns change the vowel to make plurals: man – men, foot – feet, goose – geese, tooth – teeth, mouse – mice, louse – lice; child – children.","A pronoun is used instead of a noun: Rani is a good girl. → She is a good girl. Ganesh and I went … → We went …","Sympathy expressions: I am sorry. Don’t worry. Let’s find it together. Take care."]},"qa":[["Who named Dhyan Singh as “Dhyan Chand”?","His coach."],["Where were the 1936 Olympics held?","In Berlin, Germany."],["Why did Dhyan Chand remove his shoes?","His spiked shoes made it difficult to run fast on the wet ground."],["Why did he turn down the German ruler’s offer?","He loved his country India more than money and rank."],["Whose birthday is celebrated as National Sports Day?","Major Dhyan Chand’s (29 August)."]],"act":"Collect information on any Indian Olympic medallist and prepare a chart. Describe the Annual Sports Day using the clues. Role-play Vani and John (lost notebook).","kn":"India’s hockey Olympic golds: 1928, 1932, 1936. Dhyan Chand received the Padma Bhushan.","qz":[["Dhyan Chand’s real name was ___.","Dhyan Singh","Roop Singh","Tej Singh","Chand Singh"],["Why did he practise hockey at night?","He was busy with his duty as a soldier in the day.","He did not like the sun.","The ground was free only at night.","His coach told him to sleep in the day."],["“Chand” means ___.","Moon","Sun","Star","Sky"],["The 1936 Olympics were held in ___.","Berlin","London","Delhi","Paris"],["India played the 1936 final against ___.","Germany","France","Spain","England"],["Who scored the first goal for India?","Roop Singh","Dhyan Chand","Tej Singh","Hitler"],["National Sports Day is on ___.","29 August","15 August","14 November","5 September"],["The national sport of India is ___.","Hockey","Cricket","Kabaddi","Football"],["Dhyan Chand is called the ___.","Wizard of Hockey","King of Cricket","Flying Sikh","Master Blaster"],["Plural of “tooth” is ___.","teeth","tooths","teethes","toothes"],["Plural of “mouse” is ___.","mice","mouses","meese","mouse"],["“Vinod and Suresh are playing.” Replace with a pronoun.","They","We","Us","She"],["“The book is heavy. Please put ___ on the shelf.”","it","him","her","them"],["“spectators” means ___.","people who watch a game","players","coaches","soldiers"]],"wb":{"pg":"65–80","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":71,"ws":["2.1–2.2 Passage questions, true/false, match facts, synonyms, unscramble, sports words","2.3 Antonyms and irregular plurals","2.4 Pronouns","2.5 Kind responses & role play (sympathy)","2.6 Poem – rhyming words, verbs","2.7 Rearrange sentences, Independence Day description","2.8 Comprehension • 2.9 Cricket score board","2.10 My Self Reflections • Check Point (Units 1–2)"],"mis":"Irregular plurals do not take -s: ✗ foots, tooths, mouses, childs ✓ feet, teeth, mice, children.","qz":[["Why couldn’t Dhyan Chand practise hockey during the day?","He was busy on his duty as a soldier.","He hated practising during the day.","He liked the moonlight.","He was sleeping."],["Antonym of “prepone” in the passage:","postpone","postdate","predate","prepare"],["Synonym of “victory”:","win","loss","game","team"],["Synonym of “entire”:","whole","part","half","small"],["Unscramble O G L D:","GOLD","GLOD","LODG","DOLG"],["Fill in: “The baby has tiny ___.” (foot)","feet","foots","feets","footes"],["“Mr. Teja is my father. ___ is a doctor.”","He","She","It","They"],["A kind response to “I lost my pen”:","Don’t worry, take mine.","Good for you.","Careless boy!","Go away."],["Which is a polite word?","Excuse me","Shut up","Get out","Move"],["The word “skates” rhymes with ___.","mistakes","hockey","girl","race"],["Who was the highest scorer in the Champions Trophy 2025 final score board?","Rohit","Mitchell","Shreyas","Gill"],["Our National Bird is the ___.","Peacock","Parrot","Crow","Eagle"]]},"tg":[["Activity 1 – Observe the picture (Text p.76)",["1. Different balls and sports equipment – cricket, football, tennis, hockey, volleyball.","2. Football, cricket ball, tennis ball.","3. In the school ground / playground.","4. Kabaddi / cricket (free answer).","5. Yes. A helmet protects our head from injuries (cricket, cycling, skating)."]],["Activity – Answer the questions (Text p.79)",["1. His coach.","2. In Berlin, Germany.","3. Germany.","4. He loved his country more than money and rank.","5. His spiked shoes made it hard to run on the wet ground.","6. India.","7. Major Dhyan Chand’s.","Choose: 1. (b) Dhyan Chand  2. (c) Germany  3. (c) wet  4. (b) Roop Singh  5. (c) Hockey"]],["Activities 3–5 – Irregular plurals (Text p.81–82)",["Activity 3: circle as per picture – geese, men, feet, teeth, women, lice …","Activity 4: 1. teeth  2. mice  3. feet  4. geese  5. children","Activity 5: word search – FOOTBALL, KABADDI, HOCKEY, CRICKET, TENNIS (as in grid)"]],["Activities 6–7 – Pronouns (Text p.84)",["Activity 6: She, It, He, They","Activity 7: 1. It was pretty.  2. They are friends.  3. It is tall.  4. He put out the fire.  5. She is a nurse.  6. We went to the park."]],["Activity 8 – Annual Sports Day (Text p.85)",["The Annual Sports Day of our school was celebrated on the 3rd Saturday of December. Many games were conducted. Prizes were given to the winners and mementos to the participants. The Sub-Inspector of Police was the chief guest."]],["Poem – Let us Think and Discuss (Text p.87)",["A. e.g. Ramesh – Respectful, Sita – Smart.","B. 1. Hockey  2. Geeta  3. She happily celebrated her fastest pace.  4. Kabaddi / Kho-kho  5. Outdoor games (free answer).","Rhyming: hockey – rocky, skates – mistakes, race – pace, boy – joy.","Double letters: This is my pet rabbit. It loves to eat carrots which are orange in colour. (Kitchen: kettle, coffee, apple, spoon, butter)"]],["Let us Practise (Text p.88–89)",["See workbook answer pages (Unit 2, ruled pages): 1. C) National Player 2. Player 3. b, a 4. stadium, goal 6. C) mice 7. A) They 8. C) it 9. A) are 10. B) balloon 11. B) Hockey 12. 29 August …"]]]},{"id":"en3","no":3,"t":"A Trip of Memories","m":[9],"ty":"Letter","th":"Travel & Nature","by":"Blossoms-4, Unit 3","sum":"Hemanth writes a letter to his friend Harsha about his trip to Horsley Hills, the “Ooty of Andhra Pradesh”. His family woke at 4 a.m., took a train from Vijayawada to Pakala and hired a car. The ghat road had many curves, tall trees and a cool breeze. At 1265 m above sea level they saw clouds passing by. They visited Gali Banda, the Eastern and Western viewpoints and the Mini-Zoo with crocodiles. In Madanapalle, Rabindranath Tagore translated “Jana Gana Mana” into English and Margaret Cousins composed its tune. The trip gave him lasting memories.","te":"హేమంత్ తన మిత్రుడు హర్షకు హార్సిలీ హిల్స్ (ఆంధ్రా ఊటీ) యాత్ర గురించి లేఖ రాశాడు. విజయవాడ నుండి పాకాల వరకు రైలు, అక్కడి నుండి కారులో ఘాట్ రోడ్డు మీదుగా వెళ్ళారు. గాలి బండ, తూర్పు–పడమర వ్యూపాయింట్లు, మినీ జూ (మొసళ్ళు) చూశారు. మదనపల్లెలో రవీంద్రనాథ్ ఠాగూర్ “జనగణమన”ను ఆంగ్లంలోకి అనువదించారు; మార్గరెట్ కజిన్స్ బాణీ కట్టారు.","pts":["Letter: from Hemanth (Vijayawada) to his friend Harsha.","Route: Vijayawada → (train) → Pakala → (car, ghat road) → Horsley Hills, 1265 m above sea level.","Places: Gali Banda (rocky slope, strong winds), Eastern & Western viewpoints (sunrise/sunset), Mini-Zoo (crocodiles).","Madanapalle: Tagore translated “Jana Gana Mana” from Bengali to English; Margaret Cousins composed the tune; first sung there.","Synonyms & antonyms; adjectives (tall trees, cool breeze); exclamation mark (!).","Kondapalli toys – made of soft “poniki” wood; Kondapalli Fort is over 500 years old."],"w":[["rushed","moved with great speed"],["hired","took for rent"],["scenic","beautiful natural scenery"],["breeze","a gentle wind"],["mesmerizing","very attractive"],["thrill","a sudden excitement"],["glorious","wonderful, full of beauty"],["translate","change from one language to another"],["composed","set music for a song"],["occasionally","now and then"]],"gr":{"t":"Synonyms • Antonyms • Adjectives • Exclamation mark","p":["Synonyms – words with similar meaning: quickly = hurriedly = immediately; wonderful = great.","Antonyms – opposite words: cold × hot, early × late, above × below, strong × weak.","Adjectives describe nouns: big, tall trees; dense bushes; cool breeze.","( ! ) shows sudden feeling: What a beautiful flower! Hurrah! We won!"]},"qa":[["What means of transport did Hemanth’s family use?","Auto, train and car."],["Why is Horsley Hills called the “Ooty of Andhra Pradesh”?","Because it has cool climate and beautiful scenery like Ooty."],["Name the places they visited.","Gali Banda, Eastern and Western viewpoints, Mini-Zoo and Madanapalle."],["What is the importance of Madanapalle?","Tagore translated “Jana Gana Mana” into English there; Margaret Cousins composed its tune and it was first sung there."]],"act":"Prepare a poster for the “Kite Festival” on Sankranthi using the hints. Ask five friends about places they visited and fill the table. Practise the tongue twisters.","kn":"Horsley Hills is in Annamayya (old Chittoor) district. Araku Valley has the Borra Caves and the Dhimsa tribal dance.","qz":[["To whom did Hemanth write the letter?","Harsha","Ravi","his father","his sister"],["Horsley Hills is called the ___.","Ooty of Andhra Pradesh","Kashmir of India","Ooty of Karnataka","Queen of Hills"],["At what time did Hemanth wake up?","4 a.m.","6 a.m.","5.30 a.m.","12 noon"],["From where did they hire a car?","Pakala","Vijayawada","Tirupati","Madanapalle"],["The big rocky slope with strong winds is ___.","Gali Banda","Mini-Zoo","Viewpoint","Pakala"],["What was a special attraction in the Mini-Zoo?","Crocodiles","Elephants","Lions","Giraffes"],["Who translated “Jana Gana Mana” into English?","Rabindranath Tagore","Margaret Cousins","Gandhiji","Hemanth"],["Horsley Hills is ___ metres above sea level.","1265","1000","2650","125"],["Synonym of “rushed”:","hurried","slowed down","late","stopped"],["Antonym of “early”:","late","soon","fresh","above"],["In “cool breeze”, the adjective is ___.","cool","breeze","the","touched"],["Which mark ends “What a beautiful flower”?","!","?",".",","],["Kondapalli toys are made of ___ wood.","poniki","teak","bamboo","sandal"],["“breeze” means ___.","a gentle wind","a storm","rain","a hill"]],"wb":{"pg":"81–93","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":87,"ws":["3.1–3.3 Passage questions, meanings, true/false, sequencing, alphabetical order, spellings","3.4 One-word meanings, odd one out, word web (railway station)","3.5 Adjectives","3.6 Punctuation (. , ? !)","3.7–3.8 Reading – Horsley Hills, Araku Valley","3.9 Poster analysis & writing","3.10 My Self Reflections – eco-tourism"],"mis":"Exclamation mark only for strong feelings; a question needs ( ? ). ✗ “What did you see on the trip!” ✓ “What did you see on the trip?” ✓ “What an exciting journey it was!”","qz":[["Why did Hemanth immediately share the news?","He was excited and wanted to share his happiness.","He wanted their permission.","He needed help in packing.","He was afraid."],["Packing sweaters shows Hemanth ___.","planned according to the weather","likes shopping","is careless","is lazy"],["“thrill” means ___.","a sudden excitement","a gentle wind","turnings","weather"],["“The breeze felt warm and strong” – true or false?","False","True","Not given","Both"],["Wrongly spelt word:","Passenjer","Journey","Platform","Station"],["Odd one out: train, car, auto, tree","tree","train","car","auto"],["“The view was mesmerizing” means ___.","attractive","boring","dark","small"],["Underline the adjective: “We saw colourful flowers.”","colourful","saw","flowers","We"],["Correct punctuation: “Where do you live”","?","!",".",","],["Which place did the family visit first (worksheet passage)?","View Point","Mini Zoo","Galibanda","School"],["Borra Caves are in ___.","Araku Valley","Horsley Hills","Kondapalli","Madanapalle"],["A good eco-tourism habit:","Picking up trash","Throwing plastic","Writing on rocks","Feeding wild animals"]]},"tg":[["Activity 1 – Observe the picture (Text p.90)",["1. (Free answer) e.g. Tirupati, Araku, Vizag beach.","2. e.g. Mypadu beach, Penchalakona, Udayagiri fort, Nelapattu bird sanctuary (Nellore).","3. Yes – describe a trip."]],["Answer the questions (Text p.94)",["1. Auto, train and car.","2. It is at a great height (1265 m) with many trees.","3. Because its climate and scenery are cool and beautiful like Ooty.","4. Gali Banda, viewpoints, Mini-Zoo, Madanapalle.","5. Tagore translated the National Anthem there; it was first sung there."]],["Activity 2 – Choose (Text p.95)",["1. b) Horsley Hills  2. a) a sudden excitement  3. b) Madanapalle  4. b) a big rocky stone  5. a) hurried"]],["Activities 3–4 – Synonyms & Antonyms (Text p.96–97)",["Match: share – distribute, pack – bundle, touch – feel, enjoy – delight, slope – slant","Antonyms: joyful × sad, above × below, early × late, fresh × stale, strong × weak, soft × hard"]],["Activities 5–6 – Adjectives (Text p.98)",["1. long  2. little  3. colourful  4. karate  5. sweet","Match: dark – night/sky, bright – moon/sun, … (as per columns)"]],["Activities 7–8 – Punctuation (Text p.100)",["1. Where is my pen?  2. Kiran plays cricket every day.  3. Stop! You’re making me angry!  4. Hey, look here!  5. I have a big house.  6. Will you help me?","What a beautiful morning! The birds are singing loudly. You can hear the sound of the river. It makes me feel so happy."]],["Activity 9 – Kondapalli (Text p.101)",["1. a) Kondapalli  2. d) colourful wooden toys  3. b) poniki  4. d) a local person  5. c) 500 years  6. c) colourful wooden toys"]],["Activities 10–12 – Poster & Survey (Text p.102–104)",["Poster: KITE FESTIVAL – Sankranthi celebrations | Place: outskirts of the village | Date: 15th January | Time: 9 a.m. to 5 p.m. | Events: kite flying, singing, rangoli competitions | Eligibility: 15–50 years.","Survey: record each friend’s place visited and the interesting thing."]]]},{"id":"en4","no":4,"t":"Swami Vivekananda","m":[9,10],"ty":"Biography","th":"Values & Inspiration","by":"Poem: Nation’s Strength – Ralph Waldo Emerson","sum":"Swami Vivekananda was born on 12 January 1863 in Simulia, Kolkata, to Viswanath Dutta and Bhuvaneswari Devi. He was named Veereswara but called Narendra. His mother told him stories from the Ramayana and the Mahabharata. As a child he was brave, intelligent and a leader – his favourite game was “The King and the Court”. While meditating, he did not move even when a black snake came near. Once a teacher wrongly punished him; his mother said, “Always follow the truth.” He was not afraid of a “ghost”. Inspired by the Bhagavad Gita and his guru Sri Ramakrishna Paramahamsa, he became Swami Vivekananda.","te":"స్వామి వివేకానంద 1863 జనవరి 12న కోల్‌కతాలోని సిములియాలో విశ్వనాథ దత్తా, భువనేశ్వరీ దేవి దంపతులకు జన్మించారు. అసలు పేరు వీరేశ్వరుడు, పిలుపు పేరు నరేంద్ర. చిన్నప్పటి నుండే ధైర్యం, తెలివి, నాయకత్వం కలవాడు. ధ్యానంలో ఉండగా నల్లపాము వచ్చినా కదలలేదు. ఉపాధ్యాయుడు తప్పుగా శిక్షించినా సత్యాన్నే పట్టుకున్నాడు. గురువు శ్రీ రామకృష్ణ పరమహంస.","pts":["Born: 12 January 1863, Simulia (Kolkata). Parents: Viswanath Dutta, Bhuvaneswari Devi.","Named Veereswara; called Narendra. Favourite game: “The King and the Court”.","Meditation – looked like “Little Buddha”; a black snake crawled away without harm.","Geography teacher punished him wrongly; mother: “Always follow the truth.”","Not afraid of the “ghost” in the tree – fearless. Guru: Sri Ramakrishna Paramahamsa.","Prepositions of time: at (clock time), in (months, years, seasons), on (days, dates).","Poem “Nation’s Strength” – Emerson: not gold but brave, truthful men make a nation strong."],"w":[["narrate","tell in detail"],["epic","story of a traditional hero"],["intelligence","wisdom"],["meditation","deep concentration"],["protest","a strong objection"],["furious","full of anger"],["console","comfort in grief"],["regret","feel sorry"],["spiritual","sacred"],["inspired","motivated"]],"gr":{"t":"Prepositions of time (at / in / on) • Contextual meanings • Habitual actions","p":["at – clock times: at 5 p.m., at noon, at night.","in – months, seasons, years, parts of day: in December, in summer, in 1869, in the morning.","on – days and dates: on Monday, on 15th August, on 14th November.","Habitual actions use simple present: Leela does yoga at 6 o’clock every Monday."]},"qa":[["Who were the parents of Vivekananda?","Viswanath Dutta and Bhuvaneswari Devi."],["What was he called in his childhood?","Narendra (named Veereswara)."],["What did he say to the teacher who punished him?","“I’ve not committed any error, sir. I am sure what I said is right.”"],["How did his mother console him?","“Why do you worry if you are right? Always follow the truth, whatever may happen.”"],["Whose teachings inspired him?","The Bhagavad Gita and his teacher Sri Ramakrishna Paramahamsa."]],"act":"Write a biographical note of a friend (name, birth, parents, studies, achievements). Complete the sketch of Dr. A.P.J. Abdul Kalam. Sort qualities: kind, brave, active, polite, wise (good) / foolish, timid, impolite, dull, unkind (bad).","kn":"12 January – National Youth Day (Vivekananda’s birthday). Famous quote: “Arise, awake, and stop not till the goal is reached.”","qz":[["Vivekananda was born on ___.","12 January 1863","2 October 1869","14 November 1889","15 August 1947"],["He was born in ___.","Simulia, Kolkata","Porbandar","Chennai","Howrah"],["His original name was ___.","Veereswara","Narendra","Ramakrishna","Viswanath"],["His mother told him stories from ___.","the Ramayana and the Mahabharata","the Bible","the Vedas","newspapers"],["His favourite game was ___.","The King and the Court","Kabaddi","Football","Chess"],["While meditating he looked like ___.","Little Buddha","a king","a soldier","a ghost"],["What came near the children while meditating?","A black snake","A tiger","A dog","A monkey"],["His teacher (guru) was ___.","Sri Ramakrishna Paramahamsa","Gandhiji","Tagore","Viswanath Dutta"],["“furious” means ___.","full of anger","very happy","afraid","tired"],["“Our school starts ___ 8.45 a.m.”","at","in","on","by"],["“Gandhiji was born ___ 1869.”","in","on","at","to"],["“We celebrate Independence Day ___ 15th August.”","on","in","at","by"],["According to the poem, what cannot make a people great?","Gold","Men","Truth","Brave men"],["Which is a good quality?","polite","timid","foolish","dull"]],"wb":{"pg":"94–109","f":"books/4/Class4_Workbook_Languages_Sem1.pdf","p":100,"ws":["4.1–4.3 Passage questions, match, one-word answers, sentences, unscramble, reasons, alphabetical order, sequencing","4.4 Contextual meanings, rearranging, spellings","4.5 Prepositions of time (at / in / on)","4.6 Poem “Nation’s Strength” – values","4.7 Habitual actions & biographical sketch (Jyothirao Phule)","4.8–4.9 Reading – Vivekananda, Arjun","4.10 My Self Reflections • Check Point (Units 3–4) • Misconception posters"],"mis":"at = exact time, on = day/date, in = month/year/part of day. ✗ “in 5 p.m.”, “on 1947”, “in 24th July” ✓ “at 5 p.m.”, “in 1947”, “on 24th July”, “in the night”.","qz":[["Who told Narendra stories from the epics?","his mother","his father","his friends","his grandmother"],["“intelligence” means ___.","wisdom","bravery","dedication","anger"],["“narrated” means ___.","told","sold","wrote","read"],["“Courage” means ___.","being brave","sitting quietly","ability to lead","calm thinking"],["Correct spelling:","meditation","meditetion","maditation","meditasion"],["“I wake up ___ 6 o’clock.”","at","in","on","by"],["“It is very cold ___ December.”","in","at","on","to"],["Correct sentence:","My birthday is on Friday.","My birthday is at Friday.","My birthday is in Friday.","My birthday is to Friday."],["A nation becomes weak when people are ___.","dishonest","honest","helpful","brave"],["“helping others” shows ___.","kindness","discipline","bravery","hardwork"],["Arjun was known for his ___.","courage and honesty","anger and fear","laziness and pride","greed"],["Which value: “He stayed calm when a snake came near”?","Courage","Kindness","Honesty","Discipline"]]},"tg":[["Activity 1 – Look at the picture (Text p.107)",["1. A classroom with children and a poster of Swami Vivekananda.","2. The children are celebrating/listening (Youth Day).","3. Swami Vivekananda.","4. He was a great spiritual leader; his birthday (12 January) is National Youth Day."]],["Activity 2 – Answer the questions (Text p.111)",["1. Viswanath Dutta and Bhuvaneswari Devi.","2. Narendra.","3. “I’ve not committed any error, sir. I am sure what I said is right.”","4. “My son, why do you worry if you are right? Always follow the truth, whatever may happen.”","5. The Bhagavad Gita and Sri Ramakrishna Paramahamsa.","6. Courage, honesty, concentration, love for mankind."]],["Activities 3–5 (Text p.112–114)",["Activity 3: 1. c) The King and his Court  2. c) Simulia  3. c) The Ramayana and the Mahabharata","Activity 5: 1. C) told  2. A) cleverness  3. C) failed to remember  4. C) pose  5. A) felt sorry"]],["Activity 6 – Prepositions of time (Text p.116)",["1. at 9 o’clock in the morning on Tuesday  2. at  3. at 7 o’clock in the evening on Thursday  4. On Friday, Leela watches cartoons.  5. at  6. at 6 o’clock in the evening on Sunday"]],["Activity 7 – Listening (Text p.117)",["1. c) In a small village in West Bengal  2. c) rivers  3. a) Vivekananda  4. c) to find peace"]],["Activity 9 & Poem (Text p.118–119)",["Biographical note: Name, place and date of birth, parents, studies, achievements of your friend.","Poem: 1. Brave, truthful men  2. Gold  3. For truth and honour’s sake  4. The nation’s pillars  5. strong – long, sleep – deep, fly – sky","Good qualities: kind, brave, active, polite, wise | Bad qualities: timid, foolish, impolite, dull, unkind"]],["Let us Practise (Text p.120–121)",["See workbook answer pages (Unit 4): 1. B) helpful and loving 2. Unkind 6. C) right 7. B) at 8. C) on 9. D) in 11. A) Narendra 15. Kalam – 15 Oct 1931, President, Bharat Ratna 16. B) Gold 17. C) 18. pillars"]]]}],"mat":[],"evs":[]};
